window.AlexOSQuizQuestions = [{"id":1,"q":"Орган управления в многоквартирном доме?","o":["общее собрание собственников и нанимателей в многоквартирном доме","управляющая организация","общее собрание собственников помещений в многоквартирном доме"],"a":[2],"url":"https://base.garant.ru/12138291/0add9c67393c4454d39a78904e0baac0/","cite":"ч. 1 ст. 44 ЖК РФ","explain":"Орган управления домом — общее собрание собственников помещений.","review":false},{"id":2,"q":"Необходимо ли принятие решения общего собрания собственников помещений в многоквартирном доме для приспособления общего имущества собственников помещений в многоквартирном доме с учетом потребностей инвалидов согласно требованиям, указанным в части 3 статьи 15 Жилищного кодекса Российской Федерации?","o":["необходимо","необходимо только в случае вынесения муниципальной комиссией по обследованию жилых помещений инвалидов и общего имущества в многоквартирных домах, в которых проживают инвалиды, в целях их приспособления с учетом потребностей инвалидов и обеспечения условий их доступности для инвалидов заключения о возможности приспособления жилого помещения и (или) общего имущества в многоквартирном доме, в котором проживает инвалид, с учетом потребностей инвалида и обеспечения условий их доступности для инвалида","необходимость отсутствует"],"a":[2],"url":"https://base.garant.ru/12138291/d83dadc1d9eb82a4be83885f2efeee52/","cite":"ч. 4.1 ст. 36 ЖК РФ; ч. 3 ст. 15","explain":"Решение собрания не требуется, если приспособление общего имущества для инвалидов проводится без привлечения денежных средств собственников. В вопросе это существенное условие пропущено.","review":true},{"id":3,"q":"Максимальное время дозвона в аварийно-диспетчерскую службу?","o":["не более пяти минут","не более десяти минут","законодательством Российской Федерации не установлено"],"a":[0],"url":"https://base.garant.ru/70379374/","cite":"п. 13 Правил № 416","explain":"На телефонный звонок должны ответить не более чем за 5 минут. Если ответа нет, предусмотрены обратный звонок или обработка сообщения в течение 10 минут.","review":false},{"id":4,"q":"Какое из перечисленных контрольных (надзорных) мероприятий проводится без взаимодействия с контролируемым лицом в соответствии с Федеральным законом от 31 июля 2020 г. № 248-ФЗ «О государственном контроле (надзоре) и муниципальном контроле в Российской Федерации»","o":["документарная проверка","инспекционный визит","выездное обследование"],"a":[2],"url":"https://base.garant.ru/74449814/7381fc65826091bca567a1005ba6bc41/","cite":"ст. 56, 75 Закона № 248-ФЗ","explain":"Выездное обследование проводится без взаимодействия с контролируемым лицом.","review":false},{"id":5,"q":"Какой срок предусмотрен для предоставления управляющей организацией, правлением товарищества собственников жилья, жилищным или жилищно-строительным кооперативом, иным специализированным потребительским кооперативом в уполномоченный исполнительный орган субъекта Российской Федерации, осуществляющий государственный жилищный надзор, подлинников решений и протокола общего собрания собственников помещений в многоквартирном доме?","o":["в течение десяти дней после проведения общего собрания собственников помещений в многоквартирном доме","в течение пяти дней после проведения общего собрания собственников помещений в многоквартирном доме","в течение пяти дней с момента получения управляющей организацией, правлением товарищества собственников жилья, жилищного или жилищно-строительного кооператива, иного специализированного потребительского кооператива от лица, инициировавшего общее собрание собственников помещений в многоквартирном доме, подлинников указанных документов"],"a":[2],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 1.1 ст. 46 ЖК РФ","explain":"УК направляет подлинники в жилищный надзор в течение пяти дней с момента их получения от инициатора.","review":false},{"id":6,"q":"Кто вправе инициировать проведение экспертизы качества коммунальной услуги?","o":["любой заинтересованный участник проверки факта нарушения качества коммунальной услуги","собственник помещения в многоквартирном доме","председатель совета многоквартирного дома"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 110 Правил № 354","explain":"Экспертизу вправе инициировать любой заинтересованный участник проверки качества услуги.","review":false},{"id":7,"q":"Какой срок установлен для ввода в эксплуатацию индивидуального, общего (квартирного) или комнатного прибора учета коммунальных ресурсов?","o":["не позднее месяца, следующего за датой установки прибора учета","не позднее двух месяцев, следующих за датой установки прибора учета","срок ввода в эксплуатацию приборов учета коммунальных ресурсов законодательством Российской Федерации не установлен"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 81 Правил № 354","explain":"Установленный прибор должен быть введён в эксплуатацию не позднее месяца, следующего за месяцем его установки. Для электросчётчиков действуют специальные правила.","review":false},{"id":8,"q":"На кого возложена обязанность по обеспечению надлежащего технического состояния и безопасной эксплуатации внутриквартирного газового оборудования?","o":["должностное лицо управляющей организации, правления товарищества собственников жилья, жилищного или жилищно-строительного кооператива, иного специализированного потребительского кооператива","собственник помещения в многоквартирном доме, а также лицо, пользующееся на ином законном основании помещением в многоквартирном доме, жилым домом, домовладением, потребляющее коммунальные услуги","специализированные организации"],"a":[1],"url":"https://base.garant.ru/70381684/","cite":"п. 10 Правил № 410","explain":"За надлежащее состояние и безопасную эксплуатацию внутриквартирного оборудования отвечает собственник или иной законный пользователь; обслуживание выполняет специализированная организация.","review":false},{"id":9,"q":"Какими документами определяется периодичность оказания услуг и выполнения работ, необходимых для обеспечения надлежащего содержания общего имущества собственников помещений в многоквартирном доме?","o":["договор управления многоквартирным домом","решение общего собрания собственников помещений в многоквартирном доме","договор управления многоквартирным домом, решение общего собрания собственников помещений в многоквартирном доме"],"a":[2],"url":"https://base.garant.ru/76819177/","cite":"п. 2 Правил оказания услуг № 290","explain":"Перечень и периодичность определяются и отражаются в документах, соответствующих способу управления: в частности, в договоре управления или решении собрания.","review":false},{"id":10,"q":"Какие способы оплаты за коммунальную услугу по отоплению предусмотрены жилищным законодательством Российской Федерации?","o":["в течение отопительного периода либо равномерно в течение календарного года","равномерно в течение календарного года либо исходя из показаний общедомового (коллективного) прибора учета тепловой энергии","способы оплаты за коммунальную услугу определяются на общем собрании собственников помещений в многоквартирном доме"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 42.1 Правил № 354","explain":"Предусмотрены оплата в отопительный период и равномерная оплата в течение года. Применяемый способ зависит от установленного порядка для территории.","review":false},{"id":11,"q":"Какие решения могут быть приняты уполномоченным исполнительным органом субъекта Российской Федерации, осуществляющим государственный жилищный надзор, по результатам рассмотрения заявления о внесении изменений в реестр лицензий субъекта Российской Федерации?","o":["о внесении изменений в реестр лицензий субъекта Российской Федерации, об отказе во внесении изменений в указанный реестр и возврате заявления и документов, о приостановлении рассмотрения заявления","о внесении изменений в реестр лицензий субъекта Российской Федерации и об отказе во внесении изменений в указанный реестр и возврате заявления и документов","об отказе во внесении изменений в реестр лицензий субъекта Российской Федерации и возврате заявления и документов, о приостановлении рассмотрения заявления"],"a":[0],"url":"https://base.garant.ru/71374186/","cite":"п. 7 Порядка № 938/пр","explain":"Порядок предусматривает внесение изменений, отказ с возвратом документов или приостановление рассмотрения.","review":false},{"id":12,"q":"За счет каких средств могут финансироваться услуги и (или) работы по капитальному ремонту общего имущества собственников помещений в многоквартирных домах?","o":["за счет средств федерального бюджета, бюджета субъекта Российской Федерации, местных бюджетов, взносов собственников помещений в многоквартирном доме","за счет средств федерального бюджета, бюджета субъекта Российской Федерации, местных бюджетов","за счет средств собственников помещений в многоквартирном доме"],"a":[0],"url":"https://base.garant.ru/12138291/c310495fb04e03cd147b58ba5fee6e32/","cite":"ст. 191 ЖК РФ","explain":"Капремонт может финансироваться взносами собственников и средствами государственной или муниципальной поддержки.","review":false},{"id":13,"q":"Какими способами может быть направлена заявка в аварийно-диспетчерскую службу?","o":["заявки принимаются только при непосредственном обращении в аварийно-диспетчерскую службу","заявки принимаются только посредством телефонной связи","заявки принимаются при непосредственном обращении в аварийно-диспетчерскую службу, в том числе посредством телефонной связи, а также с помощью прямой связи по переговорным устройствам, устанавливаемым в подъездах многоквартирных домов и кабинах лифтов, или других возможных средств связи"],"a":[2],"url":"https://base.garant.ru/70379374/","cite":"п. 17 Правил № 416","explain":"Заявки принимают при непосредственном обращении, по телефону, переговорным устройствам и другим доступным средствам связи.","review":false},{"id":14,"q":"К чьей компетенции относится принятие решения о выдаче лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами?","o":["к компетенции органов государственного жилищного надзора","к компетенции лицензионной комиссии субъекта Российской Федерации","к компетенции лицензионной комиссии муниципального образования Российской Федерации"],"a":[0],"url":"https://base.garant.ru/12138291/eee2dfc53c633b2005c2409be06a1d1e/","cite":"ст. 192, 194 ЖК РФ","explain":"С 1 сентября 2026 года решение о предоставлении лицензии принимает орган государственного жилищного надзора; лицензионные комиссии упразднены.","review":false},{"id":15,"q":"Какой срок установлен для передачи технической документации на многоквартирный дом при прекращении управления многоквартирным домом товариществом собственников жилья, жилищным или жилищно-строительным кооперативом, иным специализированным потребительским кооперативом?","o":["три рабочих дня с даты принятия решения общего собрания собственников помещений в многоквартирном доме об изменении способа управления домом","пять дней с даты принятия решения общего собрания собственников помещений в многоквартирном доме об изменении способа управления таким домом","десять рабочих дней с даты принятия решения общего собрания собственников помещений в многоквартирном доме об изменении способа управления домом"],"a":[0],"url":"https://base.garant.ru/12138291/61be80f84cf4d95f84aeddb3178a7797/","cite":"ч. 4 ст. 110; ч. 10 ст. 162 ЖК РФ","explain":"Срок передачи — три рабочих дня, но закон связывает его с прекращением управления/договора, а не безусловно с датой решения собрания, как написано в вариантах. Полностью точного варианта нет.","review":true},{"id":16,"q":"Структура платы за содержание жилого помещения?","o":["плата за содержание жилого помещения включает в себя плату за услуги, работы по управлению многоквартирным домом, за содержание и текущий ремонт общего имущества в многоквартирном доме, за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества в многоквартирном доме","плата за содержание жилого помещения включает в себя плату за услуги, работы по управлению многоквартирным домом, за содержание и текущий ремонт общего имущества в многоквартирном доме, за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества в многоквартирном доме, взнос на капитальный ремонт","плата за содержание жилого помещения включает в себя плату за услуги, работы по управлению многоквартирным домом, за содержание и текущий ремонт общего имущества в многоквартирном доме"],"a":[0],"url":"https://base.garant.ru/12138291/055d1b82a84145ca60b96f2b0fee8ae8/","cite":"п. 1 ч. 2 ст. 154 ЖК РФ","explain":"Плата за содержание включает управление, содержание, текущий ремонт и коммунальные ресурсы на содержание общего имущества. Капремонт — отдельный взнос.","review":false},{"id":17,"q":"Является ли основанием невнесения платы за жилое помещение и коммунальные услуги неиспользование собственниками, нанимателями и иными лицами данного помещения?","o":["является","является в случае заключения собственником, нанимателем или иным лицом соответствующего договора с исполнителем коммунальных услуг","не является"],"a":[2],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 11 ст. 155 ЖК РФ","explain":"Неиспользование помещения не освобождает от платы. Перерасчёт отдельных услуг при отсутствии производится по специальным правилам.","review":false},{"id":18,"q":"Каким документом устанавливается очередность проведения капитального ремонта общего имущества собственников помещений в многоквартирных домах?","o":["нормативный правовой акт органа государственной власти субъекта Российской Федерации","нормативные правовые акты органов местного самоуправления и органов государственной власти субъекта Российской Федерации.","нормативные правовые акты федеральных органов исполнительной власти, органов государственной власти субъектов Российской Федерации, органов местного самоуправления"],"a":[0],"url":"https://base.garant.ru/12138291/36d0c1b09e5c4695c556612dbde38197/","cite":"ч. 3 ст. 168 ЖК РФ","explain":"Очередность устанавливается региональной программой по критериям закона субъекта РФ.","review":false},{"id":19,"q":"Какой срок установлен для представления владельцем специального счета в уполномоченный исполнительный орган субъекта Российской Федерации, осуществляющий государственный жилищный надзор, уведомления о выбранном собственниками помещений в соответствующем многоквартирном доме способе формирования фонда капитального ремонта?","o":["три рабочих дня с момента открытия специального счета","пять рабочих дней с момента открытия специального счета","пять рабочих дней с момента принятия общим собранием собственников помещений в многоквартирном доме решения о выборе способа формирования фонда капитального ремонта"],"a":[1],"url":"https://base.garant.ru/12138291/2a25888d00a675bffc9a0311e7651563/","cite":"ч. 1 ст. 172 ЖК РФ","explain":"Общий срок уведомления — пять рабочих дней после открытия спецсчёта; закон субъекта может устанавливать иное.","review":false},{"id":20,"q":"Перечень обязательных работ по пожарной безопасности в многоквартирном доме?","o":["осмотры и обеспечение работоспособного состояния пожарных лестниц, систем аварийного освещения, пожаротушения, сигнализации, противопожарного водоснабжения, средств противопожарной защиты, противодымной защиты","осмотры и обеспечение работоспособного состояния пожарных лестниц, лазов, проходов, выходов, систем аварийного освещения, пожаротушения, сигнализации, противопожарного водоснабжения, средств противопожарной защиты, противодымной защиты","осмотры и обеспечение работоспособного состояния пожарных лестниц, лазов, проходов, выходов, систем аварийного освещения, пожаротушения, сигнализации, противопожарного водоснабжения, средств противопожарной защиты, противодымной защиты и другие работы, направленные на обеспечение пожарной безопасности, перечень которых устанавливается федеральным органом исполнительной власти, уполномоченным на решение задач в области пожарной безопасности"],"a":[1],"url":"https://base.garant.ru/76819177/","cite":"п. 27 Минимального перечня № 290","explain":"Перечисленные в варианте 2 осмотры и обеспечение работоспособности дословно соответствуют п. 27. Вариант 3 добавляет расплывчатую формулировку, а варианты 1–2 описывают действительные работы; единственность ответа нарушена.","review":true},{"id":21,"q":"Размер взимаемых штрафных санкций, предусмотренных с 1 мая 2015 года за осуществление предпринимательской деятельности по управлению многоквартирными домами без лицензии?","o":["от одной тысячи пятисот до двух тысяч рублей на граждан; от трех тысяч до четырех тысяч рублей на должностных лиц; от тридцати тысяч до сорока тысяч рублей на юридических лиц","от пятидесяти тысяч до ста тысяч рублей на должностных лиц; от ста пятидесяти тысяч до двухсот пятидесяти тысяч рублей на юридических лиц","от ста тысяч до двухсот пятидесяти тысяч рублей на должностных лиц; от трехсот тысяч до трехсот пятидесяти тысяч рублей на юридических лиц"],"a":[1],"url":"https://base.garant.ru/12125267/bf7fba0d52d38c54e75d77f9489477a4/","cite":"ч. 1 ст. 14.1.3 КоАП РФ","explain":"За деятельность без лицензии: должностным лицам 50–100 тыс. руб. или дисквалификация до трёх лет; юрлицам 150–250 тыс. руб. Вариант 2 верно передаёт размеры штрафов.","review":false},{"id":22,"q":"Каким документом установлены требования, соблюдение которых обеспечивает пожарную безопасность в многоквартирном доме?","o":["договор управления многоквартирным домом","Федеральный закон от 21 декабря 1994 г. № 69-ФЗ «О пожарной безопасности»","Федеральный закон от 22 июля 2008 г. № 123-ФЗ «Технический регламент о требованиях пожарной безопасности»"],"a":[2],"url":"https://base.garant.ru/12161584/8b7b3c1c76e91f88d33c08b3736aa67a/","cite":"Закон № 123-ФЗ, ст. 1, 6","explain":"Технические требования к пожарной безопасности установлены техническим регламентом № 123-ФЗ. Закон № 69-ФЗ также регулирует пожарную безопасность, поэтому вопрос сформулирован широко.","review":false},{"id":23,"q":"Каким постановлением Правительства Российской Федерации определен состав технической документации и иных документов, связанных с управлением многоквартирным домом?","o":["постановление Правительства Российской Федерации от 13 августа 2006 г. № 491 «Об утверждении Правил содержания общего имущества в многоквартирном доме и правил изменения размера платы за содержание жилого помещения в случае оказания услуг и выполнения работ по управлению, содержанию и ремонту общего имущества в многоквартирном доме ненадлежащего качества и (или) с перерывами, превышающими установленную продолжительность» (далее - постановление № 491)","постановление Правительства Российской Федерации от 15 мая 2013 г. № 416 «О порядке осуществления деятельности по управлению многоквартирными домами»","постановление Правительства Российской Федерации от 28 октября 2014 г. № 1110 «О лицензировании предпринимательской деятельности по управлению многоквартирными домами» (далее - постановление № 1110)"],"a":[0],"url":"https://base.garant.ru/12148944/","cite":"пп. 24, 26 Правил № 491","explain":"Состав технической документации и иных документов установлен Правилами содержания общего имущества № 491.","review":false},{"id":24,"q":"Какие требования относятся к лицензионным требованиям к лицензиату, соискателю лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами в соответствии с жилищным законодательством Российской Федерации?","o":["- отсутствие тождественности или схожести до степени смешения фирменного наименования соискателя лицензии или лицензиата с фирменным наименованием лицензиата, право которого на осуществление предпринимательской деятельности по управлению многоквартирными домами возникло ранее; - наличие у должностного лица (единоличного исполнительного органа юридического лица, руководителя юридического лица или его филиала либо индивидуального предпринимателя, осуществляющих управление многоквартирным домом, а в случае заключения договора о передаче полномочий единоличного исполнительного орган - единоличного исполнительного органа юридического лица или индивидуального предпринимателя, которым такие полномочия переданы) лицензиата, соискателя лицензии квалификационного аттестата; - отсутствие у должностного лица и (или) учредителя (участника) лицензиата, должностного лица и (или) учредителя (участника) соискателя лицензии неснятой или непогашенной судимости за преступления в сфере экономики, за преступления средней тяжести, тяжкие и особо тяжкие преступления","- отсутствие тождественности или схожести до степени смешения фирменного наименования соискателя лицензии или лицензиата с фирменным наименованием лицензиата, право которого на осуществление предпринимательской деятельности по управлению многоквартирными домами возникло ранее; - наличие у должностного лица (единоличного исполнительного органа юридического лица, руководителя юридического лица или его филиала либо индивидуального предпринимателя, осуществляющих управление многоквартирным домом, а в случае заключения договора о передаче полномочий единоличного исполнительного органа - единоличного исполнительного органа юридического лица или индивидуального предпринимателя, которым такие полномочия переданы) лицензиата, соискателя лицензии квалификационного аттестата; - отсутствие у должностного лица и (или) учредителя (участника) лицензиата, должностного лица и (или) учредителя (участника) соискателя лицензии неснятой или непогашенной судимости за преступления в сфере экономики, за преступления средней тяжести, тяжкие и особо тяжкие преступления; - отсутствие в сводном федеральном реестре лицензий на осуществление предпринимательской деятельности по управлению многоквартирными домами информации об аннулировании лицензии, ранее предоставленной лицензиату, соискателю лицензии","- регистрация лицензиата, соискателя лицензии в качестве юридического лица или индивидуального предпринимателя на территории Российской Федерации; - отсутствие тождественности или схожести до степени смешения фирменного наименования соискателя лицензии или лицензиата с фирменным наименованием лицензиата, право которого на осуществление предпринимательской деятельности по управлению многоквартирными домами возникло ранее; - наличие у должностного лица (единоличного исполнительного органа юридического лица, руководителя юридического лица или его филиала либо индивидуального предпринимателя, осуществляющих управление многоквартирным домом, а в случае заключения договора о передаче полномочий единоличного исполнительного органа - единоличного исполнительного органа юридического лица или индивидуального предпринимателя, которым такие полномочия переданы) лицензиата, соискателя лицензии квалификационного аттестата; - отсутствие у должностного лица и (или) учредителя (участника) лицензиата, должностного лица и (или) учредителя (участника) соискателя лицензии неснятой или непогашенной судимости за преступления в сфере экономики, за преступления средней тяжести, тяжкие и особо тяжкие преступления; - отсутствие в реестре дисквалифицированных лиц, информации о должностном лице лицензиата, должностном лице соискателя лицензии, об учредителе (участнике) лицензиата, учредителе (участнике) соискателя лицензии; - отсутствие в сводном федеральном реестре лицензий на осуществление предпринимательской деятельности по управлению многоквартирными домами информации об аннулировании лицензии, ранее предоставленной лицензиату, соискателю лицензии; - соблюдение лицензиатом требований к размещению информации, установленных частью 10.1 статьи 161 Жилищного кодекса Российской Федерации, требований к обеспечению информационного взаимодействия, предусмотренного частью 6 статьи 165 Жилищного кодекса Российской Федерации; - непривлечение к административной ответственности лицензиата, соискателя лицензии за грубое нарушение лицензионных требований в течение трех лет, предшествующих дате получения лицензии, дате продления срока ее действия; - отсутствие в Едином федеральном реестре сведений о банкротстве информации о банкротстве юридического лица, которое осуществляло деятельность по управлению многоквартирными домами и должностными лицами и (или) учредителями которого являлись должностные лица и (или) учредители соискателя лицензии, в течение трех лет, предшествующих дате обращения за лицензией такого соискателя лицензии; - соответствие лицензиата, соискателя лицензии требованиям к персоналу и материально-техническому обеспечению лицензиата, соискателя лицензии, установленным Правительством Российской Федерации, которое может быть обеспечено в том числе наличием действующего договора (договоров) на оказание услуг и (или) выполнение работ; - иные требования, установленные Правительством Российской Федерации"],"a":[2],"url":"https://base.garant.ru/12138291/9ab581f332f422774f6e67652ce80a1c/","cite":"ч. 1 ст. 193 ЖК РФ","explain":"Вариант 3 наиболее полно перечисляет требования, включая персонал и материально-техническое обеспечение. С сентября 2026 года наличие аттестата подтверждается записью в реестре.","review":false},{"id":25,"q":"Положения какого документа (каких документов) применяются при осуществлении лицензионного контроля за осуществлением предпринимательской деятельности по управлению многоквартирными домами?","o":["Жилищный кодекс Российской Федерации","Федеральный закон от 4 мая 2011 г. № 99-ФЗ «О лицензировании отдельных видов деятельности» и постановление № 1110","Жилищный кодекс Российской Федерации, Федеральный закон от 4 мая 2011 г. № 99-ФЗ «О лицензировании отдельных видов деятельности» и постановление № 1110"],"a":[2],"url":"https://base.garant.ru/12138291/18d72c687016219737622d7c0adde8e3/","cite":"ст. 196 ЖК РФ; Закон № 99-ФЗ; ПП № 1110","explain":"Применяются ЖК РФ, законодательство о лицензировании и Положение № 1110. Для процедур контроля нужно учитывать также Закон № 248-ФЗ.","review":false},{"id":26,"q":"Может ли управляющая организация являться владельцем специального счета для формирования фонда капитального ремонта многоквартирного дома?","o":["может","может по решению органа местного самоуправления об определении владельца специального счета","не может"],"a":[0],"url":"https://base.garant.ru/12138291/be812b7279e10413ff6e1603f421d2e0/","cite":"ч. 2 ст. 175 ЖК РФ","explain":"Управляющая организация может быть владельцем специального счёта при соблюдении порядка его выбора.","review":false},{"id":27,"q":"На какое расстояние должны быть удалены от многоквартирных домов, индивидуальных жилых домов, детских игровых и спортивных площадок, зданий и игровых, прогулочных и спортивных площадок организаций воспитания и обучения, отдыха и оздоровления детей и молодежи контейнерные площадки для накопления твердых коммунальных отходов согласно санитарным правилам и нормам СанПиН 2.1.3684-21 «Санитарно-эпидемиологические требования к содержанию территорий городских и сельских поселений, к водным объектам, питьевой воде и питьевому водоснабжению, атмосферному воздуху, почвам, жилым помещениям, эксплуатации производственных, общественных помещений, организации и проведению санитарно-противоэпидемических (профилактических) мероприятий», утвержденным постановлением Главного государственного санитарного врача Российской Федерации от 28 января 2021 г. № 3 (далее - СанПиН 2.1.3684-21)?","o":["не менее 20 м, но не более 100 м","не менее 30 м, но не более 150 м","не менее 50 м, но не более 200 м"],"a":[0],"url":"https://base.garant.ru/400289764/","cite":"п. 4 СанПиН 2.1.3684-21","explain":"Общее расстояние — 20–100 м. Для раздельного накопления и согласованных исключений предусмотрены специальные расстояния.","review":false},{"id":28,"q":"Порядок начисления платы за коммунальные услуги в случае отсутствия индивидуальных приборов учета коммунальных ресурсов?","o":["исходя из нормативов потребления коммунальных услуг","исходя из среднемесячного объема потребления коммунальных услуг","исходя из показаний прибора учета коммунальных ресурсов"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 42 Правил № 354","explain":"При отсутствии приборов учёта применяют нормативы с учётом предусмотренных законом исключений и повышающих коэффициентов.","review":false},{"id":29,"q":"В какой срок лицензиат обязан разместить сведения о заключении, прекращении, расторжении договора управления многоквартирным домом в государственной информационной системе жилищно-коммунального хозяйства в случае изменения перечня многоквартирных домов?","o":["пять календарных дней со дня заключения, прекращения, расторжения управления многоквартирным домом","пять рабочих дней со дня заключения, прекращения, расторжения управления многоквартирным домом","десять календарных дней со дня заключения, прекращения, расторжения управления многоквартирным домом"],"a":[1],"url":"https://base.garant.ru/12138291/13b375b9f8dbb3a21ac752265727200f/","cite":"ч. 2 ст. 198 ЖК РФ","explain":"Изменения перечня домов вследствие заключения или прекращения договора размещают в ГИС ЖКХ в течение пяти рабочих дней.","review":false},{"id":30,"q":"Подлежит ли взиманию плата за коммунальную услугу по горячему водоснабжению при отсутствии централизованного горячего водоснабжения и использовании для обеспечения потребности в горячем водоснабжении нагревательного оборудования, установленного в жилом помещении?","o":["подлежит","подлежит в случае, если собственниками помещений в многоквартирном доме в качестве способа управления выбрано непосредственное управление собственниками помещений в многоквартирном доме","не подлежит"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 54 Правил № 354","explain":"При нагреве воды индивидуальным оборудованием в квартире плата за коммунальную услугу централизованного ГВС не взимается.","review":false},{"id":31,"q":"Подлежит ли оплате потребителем ввод приборов учета коммунальных ресурсов в эксплуатацию?","o":["подлежит","подлежит в случае, если в течение трех месяцев собственник помещений в многоквартирном доме установил новый индивидуальный прибор учета коммунальных ресурсов","не подлежит"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 81.9 Правил № 354","explain":"Ввод прибора учёта в эксплуатацию осуществляется без взимания платы.","review":false},{"id":32,"q":"Какой срок установлен Жилищным кодексом Российской Федерации для обжалования в судебном порядке решения, принятого общим собранием собственников помещений в многоквартирном доме?","o":["в течение месяца со дня, когда собственник помещений в многоквартирном доме узнал или должен был узнать о принятом решении","в течение шести месяцев со дня, когда собственник помещений в многоквартирном доме узнал или должен был узнать о принятом решении","в течение шести месяцев со дня принятия собственниками помещений в многоквартирном доме соответствующего решения, если собственник не принимал участие в этом собрании или голосовал против принятия такого решения"],"a":[1],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 6 ст. 46 ЖК РФ","explain":"Срок — шесть месяцев со дня, когда собственник узнал или должен был узнать о решении, а не безусловно с даты собрания.","review":false},{"id":33,"q":"Что входит в состав платы за содержание жилого помещения?","o":["плата за услуги, работы по управлению многоквартирным домом, за содержание и текущий ремонт общего имущества в многоквартирном доме, а также за холодную воду, горячую воду, электрическую энергию, потребляемые при использовании и содержании общего имущества в многоквартирном доме, за отведение сточных вод в целях содержания общего имущества в многоквартирном доме","плата за услуги, работы по управлению многоквартирным домом, за капитальный ремонт общего имущества в многоквартирном доме, а также за холодную воду, горячую воду, электрическую энергию, потребляемые при использовании и содержании общего имущества в многоквартирном доме, за отведение сточных вод в целях содержания общего имущества в многоквартирном доме","плата за содержание и текущий ремонт общего имущества в многоквартирном доме, за коммунальные ресурсы на содержание общего имущества в многоквартирном доме, а также а также за холодную воду, горячую воду, электрическую энергию, потребляемые при использовании и содержании общего имущества в многоквартирном доме, за отведение сточных вод в целях содержания общего имущества в многоквартирном доме"],"a":[0],"url":"https://base.garant.ru/12138291/055d1b82a84145ca60b96f2b0fee8ae8/","cite":"п. 1 ч. 2 ст. 154 ЖК РФ","explain":"В составе содержания — управление, содержание, текущий ремонт и коммунальные ресурсы на общее имущество. Капремонт в эту строку не включается.","review":false},{"id":34,"q":"Является ли основанием для перерасчета размера платы за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества собственников помещений в многоквартирном доме, временное отсутствие потребителя в жилом помещении?","o":["является","не является","не является, если потребитель временно отсутствует более шести месяцев"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 88 Правил № 354","explain":"Временное отсутствие не даёт основания пересчитывать коммунальные ресурсы на общее имущество.","review":false},{"id":35,"q":"Каким образом изменяется размер платы за жилое помещение и коммунальные услуги в случае изменения формы собственности на жилое помещение?","o":["изменение формы собственности на жилое помещение является основанием изменения размера платы за коммунальные услуги","изменение формы собственности на жилое помещение является основанием изменения размера платы за коммунальные услуги в случае, если органом местного самоуправления принято соответствующее решение","изменение формы собственности на жилое помещение не является основанием изменения размера платы за коммунальные услуги"],"a":[2],"url":"https://base.garant.ru/12138291/87ed542564909a7be0ffb87814354e5b/","cite":"ч. 3 ст. 157 ЖК РФ","explain":"Изменение формы собственности не изменяет само по себе размер платы за коммунальные услуги. Формулировка вопроса шире ответа: структура платы за жильё у собственника и нанимателя различается.","review":false},{"id":36,"q":"На основании какого документа исполнитель коммунальных услуг направляет потребителю коммунальных услуг уведомление о необходимости устранить несанкционированное подключение к сетям и производит доначисление платы за коммунальную услугу, потребленную без надлежащего учета?","o":["акт осмотра внутриквартирного оборудования","акт осмотра внутридомового оборудования","акта о выявлении несанкционированного подключения"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 62 Правил № 354","explain":"Основание — акт о выявлении несанкционированного подключения; после него направляют уведомление и выполняют доначисление по правилам.","review":false},{"id":37,"q":"Размер штрафных санкций, установленный за нарушение требований жилищного законодательства Российской Федерации о передаче технической документации на многоквартирный дом и иных связанных с управлением таким многоквартирным домом документов?","o":["от двух тысяч до пяти тысяч рублей на граждан; от тридцати тысяч до сорока тысяч рублей на должностных лиц; от ста пятидесяти тысяч до двухсот тысяч рублей на юридических лиц","от четырех тысяч до пяти тысяч рублей на должностных лиц","от ста тысяч до двухсот тысяч рублей на должностных лиц; от ста пятидесяти тысяч до пятисот тысяч рублей на индивидуальных предпринимателей; от ста пятидесяти тысяч до пятисот тысяч рублей на юридических лиц"],"a":[0],"url":"https://base.garant.ru/12125267/8568985d777eca7bfadf8f28a8fcddb2/","cite":"ч. 1 ст. 7.23.2 КоАП РФ","explain":"Штрафы: гражданам 2–5 тыс., должностным лицам 30–40 тыс., юрлицам 150–200 тыс. руб. Повторное нарушение имеет отдельную санкцию.","review":false},{"id":38,"q":"Какие требования установлены к режиму работы аварийно-диспетчерской службы?","o":["аварийно-диспетчерская служба осуществляет повседневный (текущий) контроль","работа аварийно-диспетчерской службы осуществляется круглосуточно","аварийно-диспетчерская служба осуществляет повседневный (текущий) контроль, работа аварийно-диспетчерской службы осуществляется круглосуточно"],"a":[2],"url":"https://base.garant.ru/70379374/","cite":"пп. 10–12 Правил № 416","explain":"АДС ведёт текущий контроль и работает круглосуточно; вариант 3 объединяет обе характеристики.","review":false},{"id":39,"q":"За какой период определяется среднемесячный объем потребления коммунального ресурса для расчета размера платы за соответствующую коммунальную услугу в случае выхода из строя или утраты ранее введенного в эксплуатацию индивидуального, общего (квартирного), комнатного прибора учета коммунального ресурса либо истечения срока его эксплуатации?","o":["не более двух расчетных периодов подряд для жилого помещения и не более 3 расчетных периодов подряд для нежилого помещения","не более трех расчетных периодов подряд для жилого помещения и не более двух расчетных периодов подряд для нежилого помещения","не менее шести месяцев, а если период работы прибора учета составил менее шести месяцев, то за фактический период работы прибора учета, но не менее трех месяцев"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 59 Правил № 354","explain":"Среднее определяют минимум за шесть месяцев, а при меньшем сроке работы прибора — за фактический период, не менее трёх месяцев. Длительность применения среднего — отдельный вопрос.","review":false},{"id":40,"q":"Функции аварийно-диспетчерской службы?","o":["информирование органа местного самоуправления муниципального образования и лиц, осуществляющих управление многоквартирным домом, об аварийной ситуации","контроль загазованности технических подполий и коллекторов и обеспечение громкоговорящей (двусторонней) связи с пассажирами лифтов","информирование органа местного самоуправления муниципального образования и лиц, осуществляющих управление многоквартирным домом, об аварийной ситуации"],"a":[1],"url":"https://base.garant.ru/70379374/","cite":"пп. 11–14 Правил № 416","explain":"Вариант 2 соответствует п. 11 о загазованности и связи с лифтами. Варианты 1 и 3 совпадают и тоже описывают обязанность АДС по информированию. Для вопроса с единственным ответом формулировка неоднозначна.","review":true},{"id":41,"q":"Какие сроки установлены для устранения лицом, осуществляющим управление многоквартирным домом, нарушения содержания оконных и дверных заполнений помещений, относящихся к общему имуществу собственников помещений в многоквартирном доме, в отопительный период?","o":["незамедлительно","в течение суток","в течение пяти календарных дней"],"a":[1],"url":"https://base.garant.ru/12132859/","cite":"приложение № 2 к Правилам № 170","explain":"Повреждения оконных и дверных заполнений в отопительный период устраняют в течение суток.","review":false},{"id":42,"q":"Какими нормативными правовыми актами регулируется правовое положение жилищных и жилищно-строительных кооперативов?","o":["Гражданский кодекс Российской Федерации (часть первая) и Жилищный кодекс Российской Федерации","Жилищный кодекс Российской Федерации","устав жилищного или жилищно-строительного кооператива"],"a":[0],"url":"https://base.garant.ru/12138291/61be80f84cf4d95f84aeddb3178a7797/","cite":"ЖК РФ, раздел V; ГК РФ, нормы о потребительских кооперативах","explain":"Правовое положение кооперативов регулируют и гражданское, и жилищное законодательство. Устав должен им соответствовать.","review":false},{"id":43,"q":"Какие меры ответственности установлены для нанимателей жилых помещений в многоквартирном доме в случае, если наниматель и проживающие совместно с ним члены его семьи в течение более шести месяцев без уважительных причин не вносят плату за жилое помещение и коммунальные услуги?","o":["наниматель и проживающие совместно с ним члены его семьи могут быть выселены по решению собственника жилого помещения с предоставлением другого жилого помещения по договору социального найма, размер которого соответствует размеру жилого помещения, установленному для вселения граждан в общежитие","наниматель и проживающие совместно с ним члены его семьи могут быть выселены в судебном порядке с предоставлением другого жилого помещения по договору социального найма, размер которого соответствует размеру жилого помещения, установленному для вселения граждан в общежитие","наниматель и проживающие совместно с ним члены его семьи могут быть выселены в судебном порядке без предоставления другого жилого помещения"],"a":[1],"url":"https://base.garant.ru/12138291/8809e0c492096c8d84f508b2440bfb3a/","cite":"ст. 90 ЖК РФ","explain":"Возможно судебное выселение с предоставлением другого помещения по соцнайму по норме для общежития, если неуплата более шести месяцев не имела уважительных причин.","review":false},{"id":44,"q":"В соответствии с каким документом вносится нанимателем жилого помещения плата за коммунальные услуги, предоставляемые временным жильцам?","o":["дополнительное соглашение к договору социального найма с наймодателем, заключенное на срок проживания временных жильцов","нормативный правовой акт органа местного самоуправления","плата за коммунальные услуги, предоставляемые временным жильцам, не взимается"],"a":[0],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 12 ст. 155 ЖК РФ","explain":"Наниматель вносит плату за услуги временным жильцам в соответствии с дополнительным соглашением с наймодателем на срок их проживания.","review":false},{"id":45,"q":"Какие требования предъявляются к потребителю коммунальных услуг в случае обнаружения несанкционированного вмешательства в работу индивидуального прибора учета коммунальных ресурсов?","o":["о внесении доначисленной исходя из объема, рассчитанного на основании нормативов потребления соответствующих коммунальных услуг с применением повышающего коэффициента 10, платы за коммунальные услуги","об устранении несанкционированного вмешательства в работу индивидуального прибора учета коммунальных ресурсов","о внесении доначисленной исходя из объема, рассчитанного на основании нормативов потребления соответствующих коммунальных услуг с применением повышающего коэффициента 10, платы за коммунальные услуги и об устранении несанкционированного вмешательства в работу индивидуального прибора учета коммунальных ресурсов"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 81.11 Правил № 354","explain":"Предусмотрены устранение вмешательства и доначисление по нормативу с коэффициентом 10 при наличии предусмотренных правилом оснований. Для учёта электроэнергии есть специальные положения.","review":false},{"id":46,"q":"Какой срок установлен для инициатора общего собрания собственников помещений в многоквартирном доме для доведения решений, принятых на таком собрании, до всех собственников помещений в многоквартирном доме?","o":["не позднее чем через пять дней со дня принятия указанных решений","не позднее чем через десять дней со дня принятия указанных решений","срок не установлен"],"a":[1],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 3 ст. 46 ЖК РФ","explain":"Итоги и решения доводят до собственников не позднее десяти дней после принятия решений.","review":false},{"id":47,"q":"Вправе ли лицо, осуществляющее деятельность по управлению многоквартирным домом, выполнять дополнительные работы, оказывать услуги за отдельную плату?","o":["вправе без согласия потребителя выполнять дополнительные работы, оказывать услуги за плату","вправе без согласия потребителя выполнять дополнительные работы, оказывать услуги за плату, при этом потребитель вправе отказаться от оплаты таких работ (услуг)","не вправе без согласия потребителя выполнять дополнительные работы, оказывать услуги за плату, при этом потребитель вправе отказаться от оплаты таких работ (услуг), а если они оплачены, потребитель вправе потребовать от исполнителя возврата уплаченной суммы"],"a":[2],"url":"https://base.garant.ru/10106035/7a58987b486424ad79b62aa427dab1df/","cite":"ст. 16 Закона о защите прав потребителей","explain":"Платные дополнительные работы без согласия потребителя навязывать нельзя. Он может отказаться от оплаты или требовать возврата уплаченного.","review":false},{"id":48,"q":"Каким образом оформляется акт проверки качества предоставляемых коммунальных услуг в случае непроведения исполнителем коммунальных услуг проверки качества таких услуг в установленный срок?","o":["акт проверки качества предоставляемых коммунальных услуг составляется в отсутствие исполнителя коммунальной услуги и подписывается не менее чем тремя потребителями","акт проверки качества предоставляемых коммунальных услуг составляется в отсутствие исполнителя коммунальной услуги и подписывается не менее чем двумя потребителями и председателем совета многоквартирного дома, в котором не созданы товарищество или кооператив, председателем товарищества или кооператива, если управление многоквартирным домом осуществляется товариществом или кооперативом","акт проверки качества предоставляемых коммунальных услуг составляется ресурсоснабжающей организацией и направляется исполнителю коммунальных услуг"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 110.1 Правил № 354","explain":"При непроведении проверки исполнителем акт подписывают не менее двух потребителей и председатель совета дома, ТСЖ или кооператива в зависимости от способа управления.","review":false},{"id":49,"q":"Относится ли внутридомовая инженерная система газоснабжения к общему имуществу собственников помещений в многоквартирном доме?","o":["относится","относится, если собственниками помещений в многоквартирном доме принято решение о включении внутридомовой инженерной системы газоснабжения к общему имуществу собственников помещений в многоквартирном доме","не относится"],"a":[0],"url":"https://base.garant.ru/12148944/","cite":"п. 5 Правил № 491","explain":"Внутридомовая система газоснабжения входит в общее имущество в границах, установленных Правилами.","review":false},{"id":50,"q":"Какие виды осмотров установлены Правилами содержания общего имущества в многоквартирном доме, утвержденными постановлением № 491?","o":["текущие, плановые и внеплановые","только весенние и осенние","текущие, сезонные и внеочередные"],"a":[2],"url":"https://base.garant.ru/12148944/","cite":"п. 13.1 Правил № 491","explain":"Осмотры бывают текущие, сезонные и внеочередные. Текущие, в свою очередь, бывают общие и частичные.","review":false},{"id":51,"q":"Какова общая допустимая продолжительность перерыва подачи горячей воды в многоквартирном доме?","o":["8 часов (суммарно) в течение 1 года, 4 часа единовременно, при аварии на тупиковой магистрали - 24 часа подряд","8 часов (суммарно) в течение одного месяца, 4 часа единовременно, при аварии на тупиковой магистрали - 24 часа подряд (за исключением перерыва в горячем водоснабжении в связи с производством ежегодных ремонтных и профилактических работ в централизованных сетях инженерно-технического обеспечения горячего водоснабжения)","16 часов (суммарно) в течение одного месяца, 8 часов единовременно, при аварии на тупиковой магистрали - 12 часов подряд (за исключением перерыва в горячем водоснабжении в связи с производством ежегодных ремонтных и профилактических работ в централизованных сетях инженерно-технического обеспечения горячего водоснабжения)"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 4 приложения № 1 к Правилам № 354","explain":"Допускается 8 часов суммарно за месяц, 4 часа единовременно, при аварии на тупиковой магистрали — 24 часа подряд. Ежегодные профилактические отключения регулируются отдельно.","review":false},{"id":52,"q":"В чьи обязанности входит разработка и доведение до сведения собственников помещений в многоквартирном доме предложений о мероприятиях по энергосбережению и повышению энергетической эффективности?","o":["в обязанности лица, ответственного за содержание многоквартирного дома, - регулярно (не реже чем один раз в год)","в обязанности лица, осуществляющего управление многоквартирным домом, - регулярно (не реже чем один раз в квартал)","в обязанности органов местного самоуправления"],"a":[0],"url":"https://base.garant.ru/12171109/b6e02e45ca70d110df0019b9fe339c70/","cite":"ч. 7 ст. 12 Закона № 261-ФЗ","explain":"Лицо, ответственное за содержание дома, разрабатывает и доводит предложения не реже одного раза в год.","review":false},{"id":53,"q":"Каковы основные цели энергетического обследования в многоквартирном доме?","o":["получение объективных данных об объеме используемых энергетических ресурсов, определение показателей энергетической эффективности","определение потенциала энергосбережения и повышения энергетической эффективности, разработка перечня мероприятий по энергосбережению и повышению энергетической эффективности и проведение их стоимостной оценки","получение объективных данных об объеме используемых энергетических ресурсов, определение показателей энергетической эффективности, а также определение потенциала энергосбережения и повышения энергетической эффективности, разработка перечня мероприятий по энергосбережению и повышению энергетической эффективности и проведение их стоимостной оценки"],"a":[2],"url":"https://base.garant.ru/12171109/36bfb7176e3e8bfebe718035887e4efc/","cite":"ч. 2 ст. 15 Закона № 261-ФЗ","explain":"Цели обследования включают данные о ресурсах, показатели эффективности, потенциал экономии, мероприятия и оценку их стоимости.","review":false},{"id":54,"q":"Что является основанием для исключения сведений о многоквартирном доме из реестра лицензий субъекта Российской Федерации по решению уполномоченного исполнительного органа субъектов Российской Федерации, осуществляющего государственный жилищный надзор?","o":["назначение лицензиату и (или) должностному лицу, должностным лицам лицензиата в течение двенадцати месяцев судом три и более раза административного наказания за воспрепятствование законной деятельности должностного лица органа государственного жилищного надзора по проведению проверок или уклонение от таких проверок","совершение лицензиатом и (или) должностным лицом, должностными лицами лицензиата в течение двенадцати месяцев со дня назначения административного наказания за нарушение лицензионных требований, которое отнесено к грубым нарушениям лицензионных требований, такого нарушения лицензионных требований вновь","назначение лицензиату и (или) должностному лицу, должностным лицам лицензиата в течение двенадцати месяцев судом три и более раза административного наказания за воспрепятствование законной деятельности должностного лица органа государственного жилищного надзора по проведению проверок или уклонение от таких проверок, а также совершение лицензиатом и (или) должностным лицом, должностными лицами лицензиата в течение двенадцати месяцев со дня назначения административного наказания за нарушение лицензионных требований, которое отнесено к грубым нарушениям лицензионных требований, такого нарушения лицензионных требований вновь"],"a":[2],"url":"https://base.garant.ru/12138291/13b375b9f8dbb3a21ac752265727200f/","cite":"ч. 5.2–5.3 ст. 198 ЖК РФ","explain":"Оба названных основания предусмотрены: повторное грубое нарушение и три наказания за препятствование проверкам за 12 месяцев.","review":false},{"id":55,"q":"При соблюдении каких условий осуществляется перевод квартиры в многоквартирном доме в нежилое помещение?","o":["если доступ к переводимому помещению невозможен без использования помещений, обеспечивающих доступ к жилым помещениям","если квартира расположена на первом этаже многоквартирного дома, а также имеется решение общего собрания собственников помещений в многоквартирном доме","если квартира расположена на первом этаже многоквартирного дома или выше первого этажа, но помещения, расположенные непосредственно под квартирой, переводимой в нежилое помещение, не являются жилыми"],"a":[2],"url":"https://base.garant.ru/12138291/94f5bf092e8d98af576ee351987de4f0/","cite":"ст. 22–23 ЖК РФ","explain":"Вариант 3 передаёт правило об этаже и помещениях ниже. Он не исчерпывает условий перевода: нужны отдельный доступ, согласия и документы, предусмотренные законом.","review":false},{"id":56,"q":"Каким документом установлены основания изменения размера платы за коммунальные услуги при предоставлении коммунальных услуг ненадлежащего качества и (или) с перерывами, превышающими установленную продолжительность, а также при перерывах в предоставлении коммунальных услуг для проведения ремонтных и профилактических работ в пределах установленной продолжительности перерывов?","o":["федеральный закон","постановление Правительства Российской Федерации","договор управления многоквартирным домом"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"Правила № 354, раздел IX и приложение № 1","explain":"Порядок перерасчёта за качество и перерывы установлен постановлением Правительства, прежде всего № 354.","review":false},{"id":57,"q":"Какие нарушения лицензионных требований управляющими организациями признаются грубыми?","o":["- нарушение лицензионных требований, в части непроведения лицензиатом испытаний на прочность и плотность (гидравлических испытаний) узлов ввода и систем отопления, промывки и регулировки систем отопления, выполняемых в целях надлежащего содержания систем теплоснабжения (отопление, горячее водоснабжение) в многоквартирных домах; - нарушение лицензионных требований, в части незаключения в течение 30 календарных дней со дня начала исполнения договора управления многоквартирным домом договоров о выполнении работ в целях надлежащего содержания систем внутридомового газового оборудования; - нарушение лицензионных требований, в части незаключения лицензиатом в течение 30 календарных дней со дня начала исполнения договора управления многоквартирным домом договоров с ресурсоснабжающими организациями в целях приобретения коммунальных ресурсов, потребляемых при использовании и содержании общего имущества в многоквартирном доме","- нарушение лицензионных требований, в части наличия у лицензиата признанной им или подтвержденной вступившим в законную силу судебным актом задолженности перед ресурсоснабжающей организацией в размере, равном или превышающем 2 среднемесячные величины обязательств по оплате по договору ресурсоснабжения, заключенному в целях обеспечения предоставления собственникам и пользователям помещения в многоквартирном доме коммунальной услуги соответствующего вида и (или) приобретения коммунальных ресурсов, потребляемых при использовании и содержании общего имущества в многоквартирном доме, независимо от факта последующей оплаты указанной задолженности лицензиатом; - нарушение лицензионных требований, в части отказа от передачи технической документации на многоквартирный дом и иных связанных с управлением таким многоквартирным домом документов, ключей от помещений, входящих в состав общего имущества в многоквартирном доме, электронных кодов доступа к оборудованию, входящему в состав общего имущества в многоквартирном доме, и иных технических средств и оборудования, необходимых для эксплуатации многоквартирного дома и управления им; - нарушение лицензионных требований, в части непрекращения лицензиатом деятельности по управлению многоквартирным домом в течение 3 дней со дня исключения сведений о таком доме из реестра лицензий субъекта Российской Федерации, за исключением осуществления такой деятельности в соответствии с положениями части 3 статьи 200 Жилищного кодекса Российской Федерации; - нарушение лицензионных требований, в части нарушения лицензиатом требований к осуществлению аварийно-диспетчерского обслуживания","- нарушение лицензионного требования, повлекшее причинение вреда жизни или тяжкого вреда здоровью граждан, которое подтверждено вступившим в законную силу решением суда; - нарушение лицензионных требований, в части непроведения лицензиатом испытаний на прочность и плотность (гидравлических испытаний) узлов ввода и систем отопления, промывки и регулировки систем отопления, выполняемых в целях надлежащего содержания систем теплоснабжения (отопление, горячее водоснабжение) в многоквартирных домах; - нарушение лицензионных требований, в части незаключения в течение 30 календарных дней со дня начала исполнения договора управления многоквартирным домом договоров о выполнении работ в целях надлежащего содержания систем внутридомового газового оборудования, выполнении работ по эксплуатации, в том числе по обслуживанию и ремонту лифтов, подъемных платформ для инвалидов; - нарушение лицензионных требований, в части незаключения лицензиатом в течение 30 календарных дней со дня начала исполнения договора управления многоквартирным домом договоров с ресурсоснабжающими организациями в целях приобретения коммунальных ресурсов, потребляемых при использовании и содержании общего имущества в многоквартирном доме; - нарушение лицензионных требований, выполнении работ по эксплуатации, в том числе по обслуживанию и ремонту лифтов, подъемных платформ для инвалидов в части наличия у лицензиата признанной им или подтвержденной вступившим в законную силу судебным актом задолженности перед ресурсоснабжающей организацией и (или) региональным оператором по обращению с твердыми коммунальными отходами в размере, равном или превышающем 2 среднемесячные величины обязательств по оплате по договору ресурсоснабжения, заключенному в целях обеспечения предоставления собственникам и пользователям помещения в многоквартирном доме, или по договору на оказание услуг по обращению с твердыми коммунальными отходами, заключенному в целях предоставления коммунальной услуги по обращению с твердыми коммунальными отходами, коммунальной услуги соответствующего вида и (или) приобретения коммунальных ресурсов, потребляемых при использовании и содержании общего имущества в многоквартирном доме, независимо от факта последующей оплаты указанной задолженности лицензиатом; - нарушение лицензионных требований, в части отказа от передачи технической документации на многоквартирный дом и иных связанных с управлением таким многоквартирным домом документов, ключей от помещений, входящих в состав общего имущества в многоквартирном доме, электронных кодов доступа к оборудованию, входящему в состав общего имущества в многоквартирном доме, и иных технических средств и оборудования, необходимых для эксплуатации многоквартирного дома и управления им; - нарушение лицензионных требований, в части непрекращения лицензиатом деятельности по управлению многоквартирным домом в течение 3 дней со дня исключения сведений о таком доме из реестра лицензий субъекта Российской Федерации, за исключением осуществления такой деятельности в соответствии с положениями части 3 статьи 200 Жилищного кодекса Российской Федерации; - нарушение лицензионных требований, в части нарушения лицензиатом требований к осуществлению аварийно-диспетчерского обслуживания; - нарушение лицензионного требования в части обеспечения безопасности при использовании и содержании внутридомового и внутриквартирного газового оборудования при предоставлении коммунальной услуги по газоснабжению."],"a":[2],"url":"https://www.consultant.ru/document/cons_doc_LAW_170370/579bb6457855562837f1f2210f1773811cea3fb6/","cite":"п. 4.1 Положения № 1110","explain":"Вариант 3 наиболее полный. Варианты 1–2 тоже содержат действительные отдельные грубые нарушения, а текст варианта 3 имеет редакционные дефекты. Единственный ответ из формулировки не следует.","review":true},{"id":58,"q":"Каким документом определены правила пользования газом в части обеспечения безопасного использования и содержания внутридомового и внутриквартирного газового оборудования?","o":["постановление Правительства Российской Федерации от 21 июля 2008 г. № 549 «О порядке поставки газа для обеспечения коммунально-бытовых нужд граждан» (далее - постановление № 549)","постановление Правительства Российской Федерации от 14 мая 2013 г. № 410 «О мерах по обеспечению безопасности при использовании и содержании внутридомового и внутриквартирного газового оборудования» (далее - постановление № 410)","постановление № 549 и постановление № 410"],"a":[1],"url":"https://base.garant.ru/70381684/","cite":"Правила пользования газом, ПП РФ № 410","explain":"Безопасное использование и содержание ВДГО и ВКГО регулирует постановление № 410; № 549 регулирует поставку газа.","review":false},{"id":59,"q":"В какие сроки аварийно-диспетчерская служба обеспечивает ликвидацию засора мусоропровода в многоквартирном доме?","o":["незамедлительно","в течение 2 часов с момента регистрации заявки, но не ранее 8 часов и не позднее 23 часов при круглосуточном приеме заявок","в течение 2 часов с момента регистрации заявки"],"a":[1],"url":"https://base.garant.ru/70379374/","cite":"п. 13 Правил № 416","explain":"Засор мусоропровода устраняют за два часа с регистрации заявки, но работы выполняют не ранее 8:00 и не позднее 23:00; заявки принимают круглосуточно.","review":false},{"id":60,"q":"Какой срок временного отсутствия потребителя в жилом помещении является основанием для произведения исполнителем коммунальных услуг перерасчета за коммунальные услуги?","o":["более пяти полных календарных дней подряд","более десяти полных календарных дней подряд","более пятнадцати полных календарных дней подряд"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 86 Правил № 354","explain":"Временное отсутствие — более пяти полных календарных дней подряд. Право на перерасчёт зависит также от вида услуги и возможности установки счётчика.","review":false},{"id":61,"q":"Является ли обязательным обеспечение управляющей организацией свободного доступа к информации об основных показателях ее финансово-хозяйственной деятельности?","o":["является","не является, управляющая организация вправе обеспечить свободный доступ к информации об основных показателях ее финансово-хозяйственной деятельности","не является, указанная информация является коммерческой тайной"],"a":[0],"url":"https://base.garant.ru/12138291/4937220ae6cef91cd7865edfe9b471d0/","cite":"ч. 10.1 ст. 161 ЖК РФ","explain":"УК обязана обеспечивать свободный доступ к установленной информации о финансово-хозяйственной деятельности через ГИС ЖКХ.","review":false},{"id":62,"q":"Что, по общему правилу, является внешней границей эксплуатационной ответственности сетей электро-, тепло-, водоснабжения и водоотведения, входящих в состав общего имущества собственников помещений в многоквартирном доме при наличии коллективного (общедомового) прибора учета коммунального ресурса?","o":["внешняя граница стены многоквартирного дома","место соединения коллективного (общедомового) прибора учета с соответствующей инженерной сетью, входящей в многоквартирный дом","коллективный (общедомовой) прибор учета соответствующего коммунального ресурса"],"a":[1],"url":"https://base.garant.ru/12148944/","cite":"п. 8 Правил № 491","explain":"По общему правилу граница эксплуатационной ответственности — место соединения ОДПУ с входящей инженерной сетью. Не путайте с границей состава имущества по внешней стене.","review":false},{"id":63,"q":"Что является предметом энергосервисного договора (контракта)?","o":["осуществление исполнителем действий, направленных на энергосбережение и повышение энергетической эффективности использования энергетических ресурсов заказчиком","реализация исполнителем организационных, правовых, технических, технологических, экономических и иных мер, направленных на уменьшение объема используемых энергетических ресурсов при сохранении соответствующего полезного эффекта от их использования (в том числе объема произведенной продукции, выполненных работ, оказанных услуг)","осуществление исполнителем действий, направленных на энергосбережение и повышение энергетической эффективности использования энергетических ресурсов заказчиком, а также реализация исполнителем организационных, правовых, технических, технологических, экономических и иных мер, направленных на уменьшение объема используемых энергетических ресурсов при сохранении соответствующего полезного эффекта от их использования (в том числе объема произведенной продукции, выполненных работ, оказанных услуг)"],"a":[0],"url":"https://base.garant.ru/12171109/95ef042b11da42ac166eeedeb998f688/","cite":"ч. 1 ст. 19 Закона № 261-ФЗ","explain":"Предмет энергосервисного договора — действия исполнителя по энергосбережению и повышению эффективности использования ресурсов заказчиком.","review":false},{"id":64,"q":"При каком способе управления многоквартирным домом предусмотрена обязанность собственников помещений по избранию совета многоквартирного дома?","o":["управление жилищным кооперативом или иным специализированным потребительским кооперативом","управление товариществом собственников жилья","управление управляющей организацией"],"a":[2],"url":"https://base.garant.ru/12138291/c92e77552629fe24ebda390d014fe637/","cite":"ч. 1 ст. 161.1 ЖК РФ","explain":"При управлении УК совет избирают, если нет ТСЖ и домом не управляет кооператив, при числе квартир более четырёх. Это условие в вопросе опущено.","review":false},{"id":65,"q":"Вправе ли субъект Российской Федерации своим нормативным правовым актом дополнить перечень услуг и (или) работ по капитальному ремонту общего имущества собственников помещений в многоквартирном доме?","o":["вправе","вправе, если услуги и (или) работы по капитальному ремонту общего имущества в многоквартирном доме финансируются за счет средств федерального бюджета","не вправе"],"a":[0],"url":"https://base.garant.ru/12138291/2779232b3b7e6fd9fea197b64b6001e4/","cite":"ч. 2 ст. 166 ЖК РФ","explain":"Закон субъекта РФ может дополнить перечень работ, финансируемых из фонда, формируемого исходя из минимального взноса.","review":false},{"id":66,"q":"Как определяется количество голосов, которым обладает каждый собственник помещения в многоквартирном доме на общем собрании собственников помещений в данном доме?","o":["пропорционально доле собственника помещения в многоквартирном доме в праве общей собственности на общее имущество в многоквартирном доме","пропорционально размеру общей площади помещения, принадлежащего собственнику","пропорционально доле собственника помещения в многоквартирном доме в праве общей собственности на общее имущество в многоквартирном доме или пропорционально размеру общей площади помещения, принадлежащего собственнику"],"a":[0],"url":"https://base.garant.ru/12138291/92409a09f2fd78349ae7c7f2064bf25a/","cite":"ч. 3 ст. 48; ч. 1 ст. 37 ЖК РФ","explain":"Дословный ответ закона — вариант 1: голоса пропорциональны доле в общем имуществе. Доля, в свою очередь, пропорциональна площади; варианты 2–3 поэтому смыслово пересекаются с правильным.","review":true},{"id":67,"q":"Вправе ли управляющая организация осуществлять распоряжение сложившейся разницей между фактическими и планируемыми расходами по управлению многоквартирным домом?","o":["вправе, если по результатам исполнения договора управления многоквартирным домом в соответствии с размещенным в системе отчетом о выполнении договора управления фактические расходы управляющей организации оказались меньше тех, которые учитывались при установлении размера платы за содержание жилого помещения, но при условии, что полученная управляющей организацией экономия не приведет к ненадлежащему качеству оказанных услуг и (или) выполненных работ по управлению многоквартирным домом, оказанных услуг и (или) выполненных работ по содержанию и ремонту общего имущества в многоквартирном доме, и если в договоре управления многоквартирным домом не предусмотрено иное","вправе, если собственниками помещений в многоквартирном доме на общем собрании таких собственников принято решение о распоряжении сложившейся разницей между фактическими и планируемыми расходами по управлению многоквартирным домом, при условии, что полученная управляющей организацией экономия не приведет к ненадлежащему качеству оказанных услуг и (или) выполненных работ по управлению многоквартирным домом, оказанных услуг и (или) выполненных работ по содержанию и ремонту общего имущества в многоквартирном доме","не вправе"],"a":[0],"url":"https://base.garant.ru/12138291/0858e363f8cd4fd2f29032d9a6ff2b35/","cite":"ч. 12 ст. 162 ЖК РФ","explain":"Экономия остаётся УК при выполнении предусмотренных работ надлежащего качества, если договор не предусматривает иное распределение.","review":false},{"id":68,"q":"Каким документом установлено требование о проведении мероприятий, направленных на предупреждение возникновения и распространения инфекционных заболеваний, связанных с санитарным состоянием многоквартирного дома, по уничтожению насекомых и грызунов (дезинсекция и дератизация)?","o":["Федеральный закон от 30 марта 1999 г. № 52-ФЗ «О санитарно-эпидемиологическом благополучии населения»","СанПиН 2.1.3684-21","Санитарные правила и нормы СанПиН 3.3686-21 «Санитарно-эпидемиологические требования по профилактике инфекционных болезней», утвержденные постановлением Главного государственного санитарного врача Российской Федерации от 28 января 2021 г. № 4"],"a":[2],"url":"https://base.garant.ru/400342149/","cite":"СанПиН 3.3686-21, разделы о дезинсекции и дератизации","explain":"Специальные санитарные требования по профилактике инфекций, включая дезинсекцию и дератизацию, содержатся в СанПиН 3.3686-21. Общая обязанность соблюдать санитарные нормы установлена также Законом № 52-ФЗ.","review":false},{"id":69,"q":"Допустимое превышение нормативной температуры воздуха в жилом помещении при определении качества коммунальной услуги по отоплению?","o":["не более 3 °C","не более 4 °C","не допускается"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 15 приложения № 1 к Правилам № 354","explain":"Допустимое превышение нормативной температуры воздуха — не более 4 °C.","review":false},{"id":70,"q":"Установлен ли предельный уровень вносимой гражданами платы за коммунальные услуги?","o":["установлен высшим должностным лицом субъекта Российской Федерации путем утверждения предельных индексов изменения размера платы","установлен должностным лицом органа местного самоуправления путем утверждения предельных индексов изменения размера платы","не установлен"],"a":[0],"url":"https://base.garant.ru/12138291/56b29076c847d27a08432adcc6507f6e/","cite":"ст. 157.1 ЖК РФ","explain":"Предельные индексы изменения платы утверждает высшее должностное лицо субъекта РФ в установленном порядке. Это индексы роста, а не единый предел суммы каждого счёта.","review":false},{"id":71,"q":"Какой период установлен для определения температуры горячей воды в точке водоразбора в многоквартирном доме?","o":["три минуты","пять минут","десять минут"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"сноска 2 к приложению № 1 Правил № 354","explain":"Перед измерением температуры горячей воды её сливают не более трёх минут. Вопрос неточно называет это периодом определения температуры.","review":false},{"id":72,"q":"Вправе ли общее собрание собственников помещений в многоквартирном доме изменять повестку дня данного собрания?","o":["вправе","вправе, если ранее собственниками помещений в многоквартирном доме принято решение о возможности изменения повестки дня общего собрания собственников помещений в многоквартирном доме","не вправе"],"a":[2],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 2 ст. 46 ЖК РФ","explain":"Собрание не вправе менять повестку или принимать решения по вопросам, не включённым в неё.","review":false},{"id":73,"q":"Виды жилищного фонда в зависимости от целей использования?","o":["жилищный фонд социального использования и индивидуальный жилищный фонд","специализированный жилищный фонд и жилищный фонд коммерческого использования","жилищный фонд социального использования, специализированный жилищный фонд, индивидуальный жилищный фонд, жилищный фонд коммерческого использования"],"a":[2],"url":"https://base.garant.ru/12138291/95ef042b11da42ac166eeedeb998f688/","cite":"ч. 3 ст. 19 ЖК РФ","explain":"По целям использования выделяют социальный, специализированный, индивидуальный фонд и фонд коммерческого использования.","review":false},{"id":74,"q":"Что понимается под переустройством жилого помещения в многоквартирном доме?","o":["изменение конфигурации помещения, требующее внесения изменения в технический паспорт помещения в многоквартирном доме","установка, замена или перенос инженерных сетей, санитарно-технического, электрического или другого оборудования, требующие внесения изменения в технический паспорт помещения в многоквартирном доме","изменение конфигурации помещения, требующее внесения изменения в технический паспорт помещения в многоквартирном доме, а также установка, замена или перенос инженерных сетей, санитарно-технического, электрического или другого оборудования, требующие внесения изменения в технический паспорт помещения в многоквартирном доме"],"a":[1],"url":"https://base.garant.ru/12138291/53925f69af584b25346d0c0b3ee74ea1/","cite":"ч. 1 ст. 25 ЖК РФ","explain":"Переустройство — установка, замена или перенос сетей и оборудования, требующие изменения технического паспорта.","review":false},{"id":75,"q":"Основания обжалования в суде собственниками помещений в многоквартирном доме решения, принятого общим собранием собственников помещений в данном доме?","o":["в случае, если собственник помещения в многоквартирном доме не принимал участие в общем собрании собственников помещений в многоквартирном доме и таким решением нарушены его права и законные интересы","в случае, если собственник помещения в многоквартирном доме голосовал против принятия такого решения и таким решением нарушены его права и законные интересы","в случае, если собственник помещения в многоквартирном доме не принимал участие в общем собрании собственников помещений или голосовал против принятого решения и если таким решением нарушены его права и законные интересы"],"a":[2],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 6 ст. 46 ЖК РФ","explain":"Для оспаривания по этому основанию собственник не участвовал либо голосовал против, а решение нарушило его права и законные интересы.","review":false},{"id":76,"q":"Что понимается под жилищным фондом?","o":["совокупность жилых помещений, находящихся в собственности граждан и в собственности юридических лиц","совокупность жилых помещений, принадлежащих на праве собственности Российской Федерации (жилищный фонд Российской Федерации) и субъектам Российской Федерации (жилищный фонд субъектов Российской Федерации)","совокупность всех жилых помещений, находящихся на территории Российской Федерации"],"a":[2],"url":"https://base.garant.ru/12138291/95ef042b11da42ac166eeedeb998f688/","cite":"ч. 1 ст. 19 ЖК РФ","explain":"Жилищный фонд — совокупность всех жилых помещений на территории РФ.","review":false},{"id":77,"q":"Какой размер пени установлен для лиц, несвоевременно внесших плату за жилое помещение и коммунальные услуги?","o":["1/300 ставки рефинансирования Центрального банка Российской Федерации, действующей на день фактической оплаты, от не выплаченной в срок суммы за каждый день просрочки начиная с двадцать первого дня, следующего за днем наступления установленного срока оплаты, по день фактической оплаты, произведенной в течение тридцати календарных дней со дня наступления установленного срока оплаты, либо до истечения тридцати календарных дней после дня наступления установленного срока оплаты, если в тридцатидневный срок оплата не произведена","1/300 ставки рефинансирования Центрального банка Российской Федерации, действующей на день фактической оплаты, от не выплаченной в срок суммы за каждый день просрочки начиная с тридцать первого дня, следующего за днем наступления установленного срока оплаты, по день фактической оплаты, произведенной в течение шестидесяти календарных дней со дня наступления установленного срока оплаты, либо до истечения шестидесяти календарных дней после дня наступления установленного срока оплаты, если в шестидесятидневный срок оплата не произведена","1/300 ставки рефинансирования Центрального банка Российской Федерации, действующей на день фактической оплаты, от не выплаченной в срок суммы за каждый день просрочки начиная с тридцать первого дня, следующего за днем наступления установленного срока оплаты, по день фактической оплаты, произведенной в течение девяноста календарных дней со дня наступления установленного срока оплаты, либо до истечения девяноста календарных дней после дня наступления установленного срока оплаты, если в девяностодневный срок оплата не произведена"],"a":[2],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 14 ст. 155 ЖК РФ","explain":"С 31-го по 90-й день — 1/300 ставки, с 91-го дня — 1/130. Вариант 3 описывает только первый этап; фактическую ставку и исключения проверяют на дату расчёта.","review":false},{"id":78,"q":"Какой орган власти уполномочен осуществлять согласование переустройства и (или) перепланировки жилого помещения?","o":["орган местного самоуправления","орган государственного жилищного надзора","уполномоченный государственный орган субъекта Российской Федерации"],"a":[0],"url":"https://base.garant.ru/12138291/3ac805f6d87af32d44de92b042d51285/","cite":"ч. 1 ст. 26 ЖК РФ","explain":"Согласование осуществляет орган местного самоуправления; в городах федерального значения действуют предусмотренные законом особенности полномочий.","review":false},{"id":79,"q":"Для каких категорий многоквартирных домов не предусмотрено обязательное оборудование общедомовыми (коллективными) приборами учета коммунальных ресурсов?","o":["ветхие, аварийные объекты, а также объекты, мощность потребления электрической энергии которых составляет менее чем пять киловатт (в отношении организации учета используемой электрической энергии) либо максимальный объем потребления природного газа которых составляет менее чем два кубических метра в час (в отношении организации учета используемого природного газа)","ветхие, аварийные объекты, объекты, подлежащие сносу или капитальному ремонту","ветхие, аварийные объекты, объекты, подлежащие сносу или капитальному ремонту до 1 января 2013 года, а также объекты, максимальный объем потребления природного газа которых составляет менее чем два кубических метра в час (в отношении организации учета используемого природного газа)"],"a":[],"url":"https://base.garant.ru/12171109/4d6cc5b8235f826b2c67847b967f8695/","cite":"ч. 1 ст. 13 Закона № 261-ФЗ","explain":"Полностью точного варианта нет: действующая норма содержит иной состав исключений, включая отдельные аварийные и изношенные объекты; устаревшие даты и пороги нельзя считать универсальным ответом.","review":true},{"id":80,"q":"Какой порядок расчета размера платы за коммунальную услугу по отоплению предусмотрен для жилого помещения в многоквартирном доме, который оборудован коллективным (общедомовым) прибором учета тепловой энергии и в котором все жилые и нежилые помещения оборудованы индивидуальными и (или) общими (квартирными) приборами учета (распределителями) тепловой энергии?","o":["размер платы за отопление определяется исходя из объема потребленной за расчетный период в жилом или нежилом помещении в многоквартирном доме тепловой энергии, определенного при осуществлении оплаты коммунальной услуги по отоплению в течение отопительного периода по показаниям индивидуального или общего (квартирного) прибора учета в жилом или нежилом помещении","размер платы за отопление определяется исходя из объема (количества) потребленной за расчетный период в жилом или нежилом помещении в многоквартирном доме тепловой энергии, определенного при осуществлении оплаты коммунальной услуги по отоплению в течение отопительного периода по показаниям индивидуального или общего (квартирного) прибора учета в жилом или нежилом помещении и отношения общей площади помещения (жилого или нежилого) в многоквартирном доме к общей площади всех жилых и нежилых помещений в многоквартирном доме","размер платы за отопление определяется как произведение объема (количества) потребленной за расчетный период в жилом или нежилом помещении в многоквартирном доме тепловой энергии, определенного при осуществлении оплаты коммунальной услуги по отоплению в течение отопительного периода по показаниям индивидуального или общего (квартирного) прибора учета в жилом или нежилом помещении и отношения общей площади помещения (жилого или нежилого) в многоквартирном доме на тариф на тепловую энергию"],"a":[],"url":"https://base.garant.ru/12186043/","cite":"п. 42.1 и формула 3.3 приложения № 2 к Правилам № 354","explain":"Полностью корректной формулы среди вариантов нет. Учитываются индивидуальное потребление, приходящаяся на помещение доля общедомового потребления и тариф; отдельно предусмотрена оплата равномерно в течение года.","review":true},{"id":81,"q":"Предусмотрена ли оплата взносов на капитальный ремонт общего имущества собственников помещений в многоквартирном доме собственниками помещений в многоквартирном доме, который в установленном порядке признан аварийным и подлежащим сносу или реконструкции?","o":["предусмотрена","предусмотрена, в случае принятия исполнительным органом государственной власти или органом местного самоуправления решений об изъятии для государственных или муниципальных нужд земельного участка, на котором расположен этот многоквартирный дом","не предусмотрена"],"a":[2],"url":"https://base.garant.ru/12138291/48e21c9d0abeceead6308489bb637bf6/","cite":"ч. 2 ст. 169 ЖК РФ","explain":"Взносы не уплачиваются по дому, признанному аварийным и подлежащим сносу или реконструкции.","review":false},{"id":82,"q":"Предусмотрена ли жилищным законодательством Российской Федерации возможность предоставления компенсации собственникам помещений в многоквартирном доме расходов на уплату взноса на капитальный ремонт?","o":["может быть предусмотрена законом субъекта Российской Федерации","может быть предусмотрена нормативным правовым актом органа местного самоуправления","предоставление компенсации расходов на уплату взноса на капитальный ремонт жилищным законодательством Российской Федерации не предусмотрено"],"a":[0],"url":"https://base.garant.ru/12138291/48e21c9d0abeceead6308489bb637bf6/","cite":"ч. 2.1 ст. 169 ЖК РФ","explain":"Компенсация отдельным категориям собственников может предусматриваться законом субъекта РФ.","review":false},{"id":83,"q":"Какое решение принимает уполномоченный исполнительный орган субъекта Российской Федерации, осуществляющий государственный жилищный надзор, в случае, если в течение двенадцати месяцев со дня выдачи им предписания лицензиату и (или) должностному лицу, должностным лицам лицензиата, осуществляющего предпринимательскую деятельность по управлению многоквартирными домами, судом два или более раза было назначено административное наказание за неисполнение или ненадлежащее исполнение указанного предписания?","o":["о направлении документов в суд для аннулирования лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами, выданной лицензиату","об аннулировании лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами, выданной лицензиату","об исключении сведений о многоквартирных домах из реестра лицензий субъекта Российской Федерации"],"a":[2],"url":"https://base.garant.ru/12138291/13b375b9f8dbb3a21ac752265727200f/","cite":"ч. 5 ст. 198 ЖК РФ","explain":"Следствие — исключение сведений о соответствующих домах из реестра лицензий. Это не автоматическое аннулирование лицензии.","review":false},{"id":84,"q":"На какой срок выдается квалификационный аттестат, который обязаны иметь должностное лицо, должностные лица лицензиата, осуществляющего предпринимательскую деятельность по управлению многоквартирным домом?","o":["пять лет","десять лет","бессрочно"],"a":[0],"url":"https://base.garant.ru/12138291/8337deba39c434d013c9d61e5ee8f227/","cite":"ч. 6 ст. 202 ЖК РФ","explain":"Срок квалификационного аттестата — пять лет.","review":false},{"id":85,"q":"Какое решение принимает уполномоченный исполнительный орган субъекта Российской Федерации, осуществляющий государственный жилищный надзор, в случае, если в течение двенадцати месяцев лицензиату и (или) должностному лицу, должностным лицам лицензиата, осуществляющего предпринимательскую деятельность по управлению многоквартирными домами, судом три и более раза было назначено административное наказание за воспрепятствование законной деятельности должностного лица уполномоченного органа исполнительной власти субъекта Российской Федерации, осуществляющего государственный жилищный надзор, по проведению проверок или уклонение от таких проверок?","o":["о направлении в суд документов для аннулирования лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами, в отношении которых лицензиатом были совершены действия (бездействие), направленные на воспрепятствование проведению таких проверок или уклонение от таких проверок","об аннулировании лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами","об исключении из реестра лицензий субъекта Российской Федерации сведений о многоквартирном доме или обо всех многоквартирных домах, в отношении которых лицензиатом были совершены действия (бездействие), направленные на воспрепятствование проведению таких проверок или уклонение от таких проверок"],"a":[2],"url":"https://base.garant.ru/12138291/13b375b9f8dbb3a21ac752265727200f/","cite":"ч. 5.3 ст. 198 ЖК РФ","explain":"После трёх и более судебных наказаний за препятствование проверкам за 12 месяцев исключают соответствующие дома из реестра.","review":false},{"id":86,"q":"Что понимается под перепланировкой жилого помещения в многоквартирном доме?","o":["установка, замена или перенос инженерных сетей, санитарно-технического, электрического или другого оборудования, требующие внесения изменения в технический паспорт помещения в многоквартирном доме","изменение границ и (или) площади такого помещения, и (или) образование новых помещений, в том числе в случаях, предусмотренных статьей 40 Жилищного кодекса Российской Федерации, и (или) изменение его внутренней планировки (в том числе без изменения границ и (или) площади помещения). В результате перепланировки помещения также могут быть изменены границы и (или) площадь смежных помещений. Перепланировка влечет за собой необходимость внесения изменений в сведения Единого государственного реестра недвижимости о границах и (или) площади помещения (помещений) или осуществления государственного кадастрового учета образованных помещений и государственной регистрации права на образованные помещения","установка, замена или перенос инженерных сетей, санитарно-технического, электрического или другого оборудования, требующие внесения изменения в технический паспорт помещения в многоквартирном доме, а также изменение конфигурации помещения, требующее внесения изменения в технический паспорт помещения в многоквартирном доме"],"a":[1],"url":"https://base.garant.ru/12138291/53925f69af584b25346d0c0b3ee74ea1/","cite":"ч. 2 ст. 25 ЖК РФ","explain":"Перепланировка — изменение границ, площади, образование помещений или внутренней планировки с предусмотренными законом кадастровыми последствиями.","review":false},{"id":87,"q":"В каких случаях допускается определение расчетным путем объема тепловой энергии, теплоносителя по договору, заключенному между исполнителем коммунальных услуг и ресурсоснабжающей организацией?","o":["отсутствие в точках учета приборов учета и неисправность приборов учета","отсутствие в точках учета приборов учета, неисправность приборов учета и нарушение установленных договором теплоснабжения сроков представления показаний приборов учета, являющихся собственностью потребителя","неисправность приборов учета и нарушение установленных договором теплоснабжения сроков представления показаний приборов учета, являющихся собственностью потребителя"],"a":[1],"url":"https://base.garant.ru/12177489/95ef042b11da42ac166eeedeb998f688/","cite":"ч. 3 ст. 19 Закона № 190-ФЗ","explain":"Расчётный метод предусмотрен при отсутствии или неисправности приборов, а также при нарушении сроков передачи показаний в установленных случаях.","review":false},{"id":88,"q":"В какой срок управляющая организация обязана раскрывать информацию об исполнении ею договора управления многоквартирным домом в виде отчета?","o":["ежемесячно","ежеквартально","ежегодно в течение первого квартала текущего года"],"a":[2],"url":"https://base.garant.ru/12138291/4937220ae6cef91cd7865edfe9b471d0/","cite":"ч. 10.1 ст. 161 ЖК РФ","explain":"Отчёт за предыдущий год представляют и размещают в течение первого квартала текущего года. С 2025 года норма находится в ст. 161, а прежняя ч. 11 ст. 162 утратила силу.","review":false},{"id":89,"q":"При соблюдении каких требований возможно уменьшение размера общего имущества собственников помещений в многоквартирном доме?","o":["по решению управляющей организации","с согласия всех собственников помещений в многоквартирном доме путем его реконструкции","уменьшение размера общего имущества собственников помещений в многоквартирном доме невозможно"],"a":[1],"url":"https://base.garant.ru/12138291/d83dadc1d9eb82a4be83885f2efeee52/","cite":"ч. 3 ст. 36 ЖК РФ","explain":"Уменьшение общего имущества возможно с согласия всех собственников путём реконструкции.","review":false},{"id":90,"q":"Требуется ли согласие субъектов персональных данных на передачу их персональных данных лицами, которым в соответствии с Жилищным кодексом Российской Федерации вносится плата за жилое помещение и коммунальные услуги, при привлечении такими лицами представителей для осуществления расчетов с собственниками жилых помещений и взимания платы за жилое помещение и коммунальные услуги?","o":["требуется","не требуется","не требуется, если по данному вопросу собственниками помещений в многоквартирном доме принято соответствующее решение"],"a":[1],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 16 ст. 155 ЖК РФ","explain":"Для передачи данных представителям, привлекаемым для расчётов и взимания платы, отдельное согласие в предусмотренных этой нормой пределах не требуется.","review":false},{"id":91,"q":"Входит ли в состав платы за жилое помещение и коммунальные услуги оплата цены энергосервисного договора (контракта), направленного на сбережение и (или) повышение эффективности потребления коммунальных ресурсов при использовании общего имущества собственников помещений в многоквартирном доме?","o":["входит","входит, если собственниками помещений в многоквартирном доме принято решение о сбережении и (или) повышении эффективности потребления коммунальных ресурсов при использовании общего имущества собственников помещений в многоквартирном доме","не входит"],"a":[2],"url":"https://base.garant.ru/12148944/","cite":"п. 38.4 Правил № 491","explain":"Цена энергосервисного договора оплачивается отдельно от платы за жилое помещение и коммунальные услуги.","review":false},{"id":92,"q":"В каком случае наниматель жилого помещения имеет право требовать от наймодателя уменьшения платы за пользование занимаемым жилым помещением, общим имуществом в многоквартирном доме, либо возмещения своих расходов на устранение недостатков жилого помещения и (или) общего имущества собственников помещений в многоквартирном доме, либо возмещения убытков, причиненных ненадлежащим исполнением или неисполнением обязанностей наймодателем?","o":["неисполнение или ненадлежащее исполнение наймодателем жилого помещения по договору социального найма обязанности по передаче нанимателю жилого помещения","неисполнение или ненадлежащее исполнение наймодателем жилого помещения по договору социального найма обязанностей по своевременному проведению капитального ремонта жилого помещения, общего имущества в многоквартирном доме и устройств, находящихся в жилом помещении и предназначенных для предоставления коммунальных услуг","неисполнение или ненадлежащее исполнение наймодателем жилого помещения по договору социального найма обязанностей по проведению текущего ремонта жилого помещения"],"a":[1],"url":"https://base.garant.ru/12138291/ad65a43c549a45d32360a363f5d4fa2c/","cite":"ч. 2 ст. 66 ЖК РФ","explain":"Такие требования наниматель может заявить при ненадлежащем исполнении наймодателем обязанностей по капитальному ремонту.","review":false},{"id":93,"q":"Является ли энергосервисный договор (контракт), направленный на сбережение и (или) повышение эффективности потребления коммунальных ресурсов при использовании общего имущества собственников помещений в многоквартирном доме, составной частью договора управления многоквартирным домом?","o":["является","является, если собственниками помещений в многоквартирном доме принято соответствующее решение","не является"],"a":[2],"url":"https://base.garant.ru/12148944/","cite":"п. 38.2 Правил № 491","explain":"Энергосервисный договор заключается отдельно от договора управления домом.","review":false},{"id":94,"q":"Какой срок установлен для хранения сведений о назначении административного наказания в виде дисквалификации лицам, на которых уставом или иными документами управляющей организации возложена ответственность за соблюдение требований по обеспечению надлежащего содержания общего имущества собственников помещений в многоквартирном доме, сведения о которых внесены в реестр дисквалифицированных лиц?","o":["три года с даты внесения в реестр дисквалифицированных лиц","пять лет с даты внесения в реестр дисквалифицированных лиц","бессрочно"],"a":[0],"url":"https://base.garant.ru/12138291/24f445f7eb666ba9f7614c2be77e96f4/","cite":"ч. 6 ст. 195 ЖК РФ","explain":"Сведения специального жилищного реестра дисквалифицированных лиц хранят три года с даты внесения. Не путайте с общим реестром дисквалификации ФНС.","review":false},{"id":95,"q":"Какой размер штрафных санкций установлен для исполнителя коммунальных услуг за нарушение порядка расчета платы за содержание жилого помещения, повлекшее необоснованное увеличение размера такой платы?","o":["штраф в размере 30 процентов величины превышения начисленной платы за содержание жилого помещения над размером платы, которую надлежало начислить","штраф в размере 50 процентов величины превышения начисленной платы за содержание жилого помещения над размером платы, которую надлежало начислить","штраф в размере 100 процентов величины превышения начисленной платы за содержание жилого помещения над размером платы, которую надлежало начислить"],"a":[1],"url":"https://base.garant.ru/12138291/9e5648d80acc13e3bc5124970e07164b/","cite":"ч. 11 ст. 156 ЖК РФ","explain":"За необоснованное завышение платы за содержание предусмотрен штраф потребителю в размере 50% превышения с установленными законом исключениями.","review":false},{"id":96,"q":"Какой вид ответственности установлен законодательством Российской Федерации за нарушение санитарно-эпидемиологических требований к эксплуатации жилых помещений, зданий, сооружений?","o":["административная ответственность","уголовная ответственность","только гражданско-правовая ответственность"],"a":[0],"url":"https://base.garant.ru/12125267/8e5cab37391b571c12c39a49736d35f9/","cite":"ст. 6.4 КоАП РФ","explain":"За нарушение санитарных требований к эксплуатации помещений установлена административная ответственность; конкретные обстоятельства могут образовывать и другие составы.","review":false},{"id":97,"q":"В какой срок со дня получения уведомления от уполномоченного исполнительного органа субъекта Российской Федерации, осуществляющего государственный жилищный надзор, об исключении сведений о многоквартирном доме из реестра лицензий субъекта Российской Федерации, о прекращении действия лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами, об ее аннулировании орган местного самоуправления созывает общее собрание собственников помещений в многоквартирном доме для решения вопроса о выборе способа управления таким домом?","o":["семь календарных дней со дня получения уведомления","пятнадцать календарных дней со дня получения уведомления","тридцать календарных дней со дня получения уведомления"],"a":[1],"url":"https://base.garant.ru/12138291/56ae36fc84d31bc2f9c0b07177fa16a9/","cite":"ч. 4 ст. 200 ЖК РФ","explain":"ОМСУ созывает собрание в течение пятнадцати дней после получения уведомления.","review":false},{"id":98,"q":"Какая обязанность установлена для собственника жилого дома или части жилого дома по обеспечению обращения с твердыми коммунальными отходами?","o":["заключение с региональным оператором по обращению с твердыми коммунальными отходами договора на оказание услуг по обращению с твердыми коммунальными отходами","заключение с оператором по обращению с твердыми коммунальными отходами договора на оказание услуг по сбору, накоплению, транспортированию, обработке, утилизации, обезвреживанию, размещению твердых коммунальных отходов","самостоятельное осуществление действий по сбору, транспортированию, обезвреживанию и размещению твердых коммунальных отходов"],"a":[0],"url":"https://base.garant.ru/12138291/7d6bbe1829627ce93319dc72963759a2/","cite":"ч. 5 ст. 30 ЖК РФ","explain":"Собственник жилого дома или его части заключает договор обращения с ТКО с региональным оператором.","review":false},{"id":99,"q":"Какой срок установлен для собственников помещений в многоквартирном доме для принятия на общем собрании собственников помещений в многоквартирном доме решения о продолжении осуществления лицензиатом деятельности по управлению данным многоквартирным домом в случае наличия оснований для исключения сведений о многоквартирном доме из реестра лицензий субъекта Российской Федерации?","o":["один месяц со дня их надлежащего информирования","два месяца со дня их надлежащего информирования","три месяца со дня их надлежащего информирования"],"a":[1],"url":"https://base.garant.ru/12138291/13b375b9f8dbb3a21ac752265727200f/","cite":"ч. 7 ст. 198 ЖК РФ","explain":"Собственникам предоставлены два месяца после надлежащего информирования для решения о продолжении управления в предусмотренных законом случаях.","review":false},{"id":100,"q":"Какой датой определяется обязанность приступить к предоставлению коммунальных услуг потребителям в многоквартирном доме управляющей организацией, выбранной по решению общего собрания собственников помещений в многоквартирном доме либо по результатам проведения открытого конкурса по отбору управляющей организации для управления многоквартирным домом?","o":["с даты внесения изменений в реестр лицензий субъекта Российской Федерации в связи с заключением договора управления многоквартирным домом","с даты заключением договора управления многоквартирным домом","с даты принятия собственниками помещений решения о выборе управляющей организации либо с момента заключения договора управления по результатам открытого конкурса по отбору управляющей организации"],"a":[0],"url":"https://base.garant.ru/12138291/0858e363f8cd4fd2f29032d9a6ff2b35/","cite":"ч. 7 ст. 162 ЖК РФ; п. 14 Правил № 354","explain":"УК приступает к исполнению договора с даты изменения реестра лицензий в связи с заключением договора управления.","review":false},{"id":101,"q":"В чьи обязанности входит обеспечение надлежащей эксплуатации общедомовых (коллективных) приборов учета коммунальных ресурсов, их сохранность и своевременная замена в соответствии с Правилами содержания общего имущества в многоквартирном доме, утвержденными постановлением № 491?","o":["собственники помещений в многоквартирном доме","ресурсоснабжающая организация","совет многоквартирного дома"],"a":[0],"url":"https://base.garant.ru/12148944/","cite":"п. 18 Правил № 491","explain":"Общая обязанность обеспечивать установку, сохранность и эксплуатацию ОДПУ возлагается на собственников. Для электрических приборов есть исключение — обязанности гарантирующего поставщика.","review":false},{"id":102,"q":"На какой срок может устанавливаться плата за содержание жилого помещения общим собранием собственников помещений в многоквартирном доме?","o":["не более чем один год","не менее чем один год","не менее чем три года"],"a":[1],"url":"https://base.garant.ru/12138291/9e5648d80acc13e3bc5124970e07164b/","cite":"ч. 7 ст. 156 ЖК РФ","explain":"Размер платы за содержание устанавливают на срок не менее одного года.","review":false},{"id":103,"q":"С какой периодичностью исполнитель коммунальных услуг обязан проводить проверки достоверности передаваемых потребителями коммунальных услуг сведений о показаниях индивидуальных, общих (квартирных), комнатных приборов учета коммунальных ресурсов (распределителей), установленных в жилых (нежилых) помещениях, и проверки состояния указанных приборов учета?","o":["не чаще одного раза в три месяца","не реже одного раза в шесть месяцев","не чаще одного раза в год"],"a":[],"url":"https://base.garant.ru/12186043/","cite":"п. 83 Правил № 354","explain":"Общее правило — не реже одного раза в год; при доступе в жилое помещение — не чаще одного раза в три месяца. Ни один вариант не передаёт общее правило полностью; вариант 1 описывает только ограничение частоты.","review":true},{"id":104,"q":"Какая информация запрещена для размещения на платежных документах для внесения платы за жилое помещение и коммунальные услуги, в том числе на оборотной стороне?","o":["реклама","социальная реклама","справочно-информационные сведения"],"a":[0],"url":"https://base.garant.ru/12145525/5633a92d35b966c2ba2f1e859e7bdd69/","cite":"ч. 10.3 ст. 5 Закона № 38-ФЗ","explain":"Реклама на платёжных документах запрещена, за исключением социальной рекламы и справочно-информационных сведений.","review":false},{"id":105,"q":"Какие существенные условия энергосервисного договора (контракта) установлены Федеральным законом от 23 ноября 2009 г. № 261-ФЗ «Об энергосбережении и о повышении энергетической эффективности и о внесении изменений в отдельные законодательные акты Российской Федерации»?","o":["величина экономии энергетических ресурсов (в том числе в стоимостном выражении) и срок действия энергосервисного договора (контракта)","обязанность исполнителя по обеспечению при использовании энергетических ресурсов согласованных режимов и условий использования энергетических ресурсов (включая температурный режим, уровень освещенности, другие характеристики, соответствующие требованиям в области организации труда, содержания зданий, строений, сооружений) и по установке и вводу в эксплуатацию приборов учета используемых энергетических ресурсов","величина экономии энергетических ресурсов (в том числе в стоимостном выражении) и срок действия энергосервисного договора (контракта), обязанность исполнителя по обеспечению при использовании энергетических ресурсов согласованных режимов и условий использования энергетических ресурсов (включая температурный режим, уровень освещенности, другие характеристики, соответствующие требованиям в области организации труда, содержания зданий, строений, сооружений) и по установке и вводу в эксплуатацию приборов учета используемых энергетических ресурсов"],"a":[0],"url":"https://base.garant.ru/12171109/95ef042b11da42ac166eeedeb998f688/","cite":"ч. 2–3 ст. 19 Закона № 261-ФЗ","explain":"Обязательны величина экономии и срок, достаточный для её достижения. Условия об установке счётчиков и режимах использования относятся к возможным дополнительным условиям.","review":false},{"id":106,"q":"Каким образом осуществляется начисление платы за коммунальные услуги, предоставленные потребителям в жилых помещениях в общежитиях коридорного, гостиничного и секционного типа (с наличием на этажах общих кухонь, туалетов или блоков душевых)?","o":["в порядке, установленном для расчета размера платы за коммунальные услуги для потребителей, проживающих в квартире","в порядке, установленном для расчета размера платы за коммунальные услуги для потребителей, проживающих в коммунальной квартире","в порядке, установленном для расчета размера платы за коммунальные услуги для потребителей, проживающих в части жилого дома"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 51 Правил № 354","explain":"В общежитиях с общими кухнями и санитарными помещениями применяют порядок расчёта для коммунальной квартиры.","review":false},{"id":107,"q":"Каков срок действия лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами?","o":["пять лет","десять лет","бессрочно"],"a":[0],"url":"https://base.garant.ru/12138291/eee2dfc53c633b2005c2409be06a1d1e/","cite":"ч. 4 ст. 192 ЖК РФ","explain":"Лицензия предоставляется на пять лет с возможностью продления в установленном порядке.","review":false},{"id":108,"q":"Перечень лиц лицензиата, осуществляющего предпринимательскую деятельность по управлению многоквартирными домами, которые обязаны иметь квалификационного аттестата?","o":["единоличный исполнительный орган лицензиата - юридического лица, руководитель лицензиата - юридического лица или его филиала либо лицензиат - индивидуальный предприниматель","единоличный исполнительный орган юридического лица или индивидуальный предприниматель, которым лицензиатом - юридическим лицом переданы полномочия его единоличного исполнительного органа","единоличный исполнительный орган лицензиата - юридического лица, руководитель лицензиата - юридического лица или его филиала либо лицензиат - индивидуальный предприниматель, единоличный исполнительный орган юридического лица или индивидуальный предприниматель, которым лицензиатом - юридическим лицом переданы полномочия его единоличного исполнительного органа"],"a":[2],"url":"https://base.garant.ru/12138291/9ab581f332f422774f6e67652ce80a1c/","cite":"п. 2 ч. 1 ст. 193; ст. 202 ЖК РФ","explain":"Требование охватывает руководителя/единоличный исполнительный орган, ИП, а также лицо, которому переданы полномочия единоличного исполнительного органа.","review":false},{"id":109,"q":"Кто вправе инициировать внеочередное общее собрание собственников помещений в многоквартирном доме?","o":["любой собственник помещения в многоквартирном доме","только орган местного самоуправления в случаях, предусмотренных Жилищным кодексом Российской Федерации","только управляющая организация, либо правление товарищества собственников жилья, жилищного или жилищно-строительного кооператива, иного специализированного потребительского кооператива"],"a":[0],"url":"https://base.garant.ru/12138291/c7f0164139c159e5c4e7786790ae469d/","cite":"ч. 2 ст. 45 ЖК РФ","explain":"Любой собственник может инициировать внеочередное собрание. Это не исключает иных предусмотренных законом инициаторов.","review":false},{"id":110,"q":"Каким документом установлен порядок составления акта проверки факта предоставления коммунальных услуг ненадлежащего качества и (или) с перерывами, превышающими установленную продолжительность?","o":["Правила предоставления коммунальных услуг собственникам и пользователям помещений в многоквартирных домах и жилых домов, утвержденные постановлением Правительства Российской Федерации от 6 мая 2011 г. № 354 «О предоставлении коммунальных услуг собственникам и пользователям помещений в многоквартирных домах и жилых домов» (далее - постановление № 354)","Правила изменения размера платы за содержание жилого помещения в случае оказания услуг и выполнения работ по управлению, содержанию и ремонту общего имущества в многоквартирном доме ненадлежащего качества и (или) с перерывами, превышающими установленную продолжительность, утвержденные постановлением № 491","Минимальный перечень услуг и работ, необходимых для обеспечения надлежащего содержания общего имущества в многоквартирном доме, и порядке их оказания лнения, утвержденный постановлением Правительства Российской Федерации ля 2013 г. № 290 «О минимальном перечне услуг и работ, необходимых для обеспечения надлежащего содержания общего имущества в многоквартирном доме, дке их оказания и выполнения» (далее - постановление № 290)"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"пп. 104–113 Правил № 354","explain":"Порядок фиксации нарушения качества коммунальных услуг и составления акта установлен Правилами № 354.","review":false},{"id":111,"q":"Могут ли включаться в плату за коммунальную услугу по отоплению и (или) горячему водоснабжению, для оказания которых используется оборудование, входящее в состав общего имущества собственников помещений в многоквартирном доме, расходы на содержание и ремонт такого оборудования?","o":["подлежат включению в случае принятия собственниками помещений в многоквартирном доме соответствующего решения","подлежат включению, если услуги произведены с использованием указанного оборудования","не подлежат, если услуги произведены с использованием указанного оборудования"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 54 Правил № 354","explain":"Содержание и ремонт общего оборудования оплачивают в составе содержания жилья, не включают повторно в стоимость произведённых с его помощью коммунальных услуг.","review":false},{"id":112,"q":"В каких случаях теплоснабжающая организация вправе ввести ограничения подачи тепловой энергии, теплоносителя в многоквартирный дом?","o":["использование потребителем бытовых машин (приборов, оборудования), мощность подключения которых превышает максимально допустимые нагрузки, рассчитанные исполнителем исходя из технических характеристик внутридомовых инженерных систем и доведенные до сведения потребителей, - с момента выявления нарушения","выявление факта несанкционированного подключения внутриквартирного оборудования потребителя к внутридомовым инженерным системам или централизованным сетям инженерно-технического обеспечения - с момента выявления несанкционированного подключения","использование потребителем бытовых машин (приборов, оборудования), мощность подключения которых превышает максимально допустимые нагрузки, рассчитанные исполнителем исходя из технических характеристик внутридомовых инженерных систем и доведенные до сведения потребителей, - с момента выявления нарушения, выявление факта несанкционированного подключения внутриквартирного оборудования потребителя к внутридомовым инженерным системам или централизованным сетям инженерно-технического обеспечения - с момента выявления несанкционированного подключения"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 115 Правил № 354; ст. 22 Закона № 190-ФЗ","explain":"Вариант 3 объединяет основания, перечисленные для исполнителя коммунальных услуг в п. 115. Вопрос о теплоснабжающей организации и ограничении целого дома требует иных условий и защиты добросовестных потребителей; без них ответ неоднозначен.","review":true},{"id":113,"q":"Подлежит ли ежегодному переутверждению на общем собрании собственников помещений в многоквартирном доме перечень услуг и работ, необходимых для обеспечения надлежащего содержания общего имущества собственников помещений в многоквартирном доме?","o":["подлежит","подлежит, если договором управления не предусмотрено иное","не подлежит"],"a":[2],"url":"https://base.garant.ru/76819177/","cite":"п. 2 Правил № 290; ч. 3, 8 ст. 162 ЖК РФ","explain":"Общей обязанности ежегодно заново утверждать действующий перечень нет. Его изменение оформляют по договору и закону.","review":false},{"id":114,"q":"На кого возложена обязанность по обеспечению надлежащего содержания дымовых и вентиляционных каналов в многоквартирных домах?","o":["лица, ответственные за содержание общего имущества в многоквартирном доме","лица, осуществляющие управление многоквартирным домом","специализированная организация"],"a":[0],"url":"https://base.garant.ru/70381684/","cite":"п. 11 Правил № 410","explain":"Надлежащее содержание дымовых и вентиляционных каналов обеспечивает лицо, ответственное за содержание общего имущества, с привлечением исполнителя необходимых работ.","review":false},{"id":115,"q":"Учитывается ли в общей площади жилого помещения в многоквартирном доме площадь лоджии/балкона?","o":["учитывается","учитывается, если площадь лоджии/балкона включена в технический паспорт многоквартирного дома","не учитывается"],"a":[2],"url":"https://base.garant.ru/12138291/36bfb7176e3e8bfebe718035887e4efc/","cite":"ч. 5 ст. 15 ЖК РФ","explain":"Балконы, лоджии, веранды и террасы не входят в общую площадь жилого помещения по ЖК РФ.","review":false},{"id":116,"q":"Какая периодичность проведения общих собраний собственников помещений в многоквартирном доме определена жилищным законодательством Российской Федерации?","o":["ежеквартально","ежегодно","периодичность не определена"],"a":[1],"url":"https://base.garant.ru/12138291/c7f0164139c159e5c4e7786790ae469d/","cite":"ч. 1 ст. 45 ЖК РФ","explain":"Собственники обязаны ежегодно проводить годовое общее собрание.","review":false},{"id":117,"q":"Виды жилых помещений в многоквартирном доме?","o":["жилой дом, квартира, комната","квартира, комната","квартира"],"a":[1],"url":"https://base.garant.ru/12138291/7a58987b486424ad79b62aa427dab1df/","cite":"ст. 16 ЖК РФ","explain":"Внутри многоквартирного дома жилыми помещениями являются квартиры и комнаты; жилой дом как отдельное здание не является помещением в МКД.","review":false},{"id":118,"q":"Что понимается под квартирой в многоквартирном доме?","o":["структурно обособленное помещение в многоквартирном доме, обеспечивающее возможность прямого доступа к помещениям общего пользования в таком доме и состоящее из одной или нескольких комнат, а также помещений вспомогательного использования, предназначенных для удовлетворения гражданами бытовых и иных нужд, связанных с их проживанием в таком обособленном помещении","индивидуально-определенное здание, которое состоит из комнат, а также помещений вспомогательного использования, предназначенных для удовлетворения гражданами бытовых и иных нужд, связанных с их проживанием в таком здании","часть жилого дома, предназначенная для использования в качестве места непосредственного проживания граждан в жилом доме"],"a":[0],"url":"https://base.garant.ru/12138291/7a58987b486424ad79b62aa427dab1df/","cite":"ч. 3 ст. 16 ЖК РФ","explain":"Квартира — структурно обособленное помещение с прямым доступом к общим помещениям, состоящее из комнат и вспомогательных помещений.","review":false},{"id":119,"q":"Что понимается под комнатой в жилом помещении?","o":["структурно обособленное помещение в многоквартирном доме, обеспечивающее возможность прямого доступа к помещениям общего пользования в таком доме и состоящее из одной или нескольких комнат, а также помещений вспомогательного использования, предназначенных для удовлетворения гражданами бытовых и иных нужд, связанных с их проживанием в таком обособленном помещении","индивидуально-определенное здание, которое состоит из комнат, а также помещений вспомогательного использования, предназначенных для удовлетворения гражданами бытовых и иных нужд, связанных с их проживанием в таком здании","часть жилого дома или квартиры, предназначенная для использования в качестве места непосредственного проживания граждан в жилом доме или квартире"],"a":[2],"url":"https://base.garant.ru/12138291/7a58987b486424ad79b62aa427dab1df/","cite":"ч. 4 ст. 16 ЖК РФ","explain":"Комната — часть жилого дома или квартиры, предназначенная для непосредственного проживания граждан.","review":false},{"id":120,"q":"Что является предметом государственного жилищного надзора?","o":["соблюдение юридическими лицами, индивидуальными предпринимателями и гражданами обязательных требований, установленных жилищным законодательством, законодательством об энергосбережении и о повышении энергетической эффективности, законодательством о газоснабжении в Российской Федерации в отношении жилищного фонда, за исключением муниципального жилищного фонда","соблюдение юридическими лицами, индивидуальными предпринимателями и гражданами обязательных требований, установленных жилищным законодательством, законодательством об энергосбережении и о повышении энергетической эффективности в отношении жилищного фонда","соблюдение юридическими лицами, индивидуальными предпринимателями и гражданами обязательных требований, установленных жилищным законодательством в отношении жилищного фонда"],"a":[0],"url":"https://base.garant.ru/12138291/9e3305d0d08ff111955ebd93afd10878/","cite":"ч. 1 ст. 20 ЖК РФ","explain":"Предмет регионального жилищного надзора включает перечисленные обязательные требования к жилищному фонду, кроме муниципального фонда.","review":false},{"id":121,"q":"К чьей компетенции относится принятие решения о переводе жилого помещения в нежилое помещение и нежилого помещения в жилое помещение?","o":["органы местного самоуправления","уполномоченные исполнительные органы субъектов Российской Федерации","органы местного самоуправления, уполномоченные органы исполнительной власти субъектов Российской Федерации"],"a":[0],"url":"https://base.garant.ru/12138291/74d7c78a3a1e33cef2750a2b7b35d2ed/","cite":"ч. 1 ст. 23 ЖК РФ","explain":"Решение о переводе принимает орган местного самоуправления с учётом предусмотренных законом особенностей для отдельных территорий.","review":false},{"id":122,"q":"Какая мера административной ответственности установлена для должностных лиц за уклонение от заключения договора о техническом обслуживании и ремонте внутридомового и (или) внутриквартирного газового оборудования?","o":["предупреждение","административный штраф в размере от двадцати пяти тысяч до ста тысяч рублей","дисквалификация на срок от восемнадцати месяцев до трех лет"],"a":[1],"url":"https://base.garant.ru/12125267/010e737008c9a9eda2060a892be6e9f1/","cite":"ч. 2 ст. 9.23 КоАП РФ","explain":"За уклонение от обязательного договора ТО газового оборудования для должностного лица предусмотрен штраф 25–100 тыс. руб.","review":false},{"id":123,"q":"В какой срок орган местного самоуправления обязан провести внеплановую проверку деятельности управляющей организации при поступлении обращения собственников помещений в многоквартирном доме, председателя совета многоквартирного дома, органов управления товарищества собственников жилья либо органов управления жилищного кооператива или органов управления иного специализированного потребительского кооператива о невыполнении управляющей организацией обязательств по договору управления многоквартирным домом?","o":["пять календарных дней","десять календарных дней","пятнадцать календарных дней"],"a":[0],"url":"https://base.garant.ru/12138291/573825caadc5febfea5a29ea7d10772c/","cite":"ч. 1.1 ст. 165 ЖК РФ","explain":"Норма устанавливает пятидневный срок проверки по соответствующему обращению. При применении учитываются действующие правила и ограничения контрольной деятельности.","review":false},{"id":124,"q":"В каких случаях управляющая организация обязана организовать проведение общего собрания собственников помещений в многоквартирном доме?","o":["поступление в управляющую организацию или правление товарищества собственников жилья, жилищного или жилищно-строительного кооператива, иного специализированного потребительского кооператива обращения от граждан","поступление в управляющую организацию или правление товарищества собственников жилья, жилищного или жилищно-строительного кооператива, иного специализированного потребительского кооператива в письменной форме обращения от собственников помещений, обладающих не менее чем десятью процентами голосов от общего количества голосов собственников помещений в многоквартирном доме","управляющая организация не вправе организовывать проведение общего собрания собственников помещений в многоквартирном доме"],"a":[1],"url":"https://base.garant.ru/12138291/c7f0164139c159e5c4e7786790ae469d/","cite":"ч. 6 ст. 45 ЖК РФ","explain":"УК обязана организовать собрание по письменному обращению собственников с не менее чем 10% голосов.","review":false},{"id":125,"q":"С какого момента у собственника жилого помещения возникает обязанность по внесению платы за жилое помещение и коммунальные услуги?","o":["с момента возникновения права собственности на жилое помещение","с момента предоставления жилого помещения","с момента подписания договора управления многоквартирным домом"],"a":[0],"url":"https://base.garant.ru/12138291/75f098e5997a1f43e69b4da6f96124a5/","cite":"п. 5 ч. 2 ст. 153 ЖК РФ","explain":"Общее основание для собственника — возникновение права собственности. Для принятия помещения от застройщика и иных случаев есть специальные нормы.","review":false},{"id":126,"q":"Может ли один совет многоквартирного дома быть избран в отношении нескольких многоквартирных домов?","o":["может","может, в случае принятия решения на общем собрании собственников помещений в многоквартирном доме","не может"],"a":[2],"url":"https://base.garant.ru/12138291/c92e77552629fe24ebda390d014fe637/","cite":"ч. 1 ст. 161.1 ЖК РФ","explain":"Один совет нельзя избирать для нескольких многоквартирных домов.","review":false},{"id":127,"q":"Как в платежном документе отражается размер платы за содержание жилого помещения в части оплаты коммунальных ресурсов, потребляемых при содержании общего имущества собственников помещений в многоквартирном доме?","o":["отдельной строкой по каждому виду ресурсов","одной строкой для всех видов ресурсов","не отражается"],"a":[0],"url":"https://base.garant.ru/12148944/","cite":"п. 29.4 Правил № 491","explain":"Плата за ресурсы на содержание общего имущества отражается отдельно по каждому виду ресурсов.","review":false},{"id":128,"q":"К полномочиям какого органа государственной власти относится утверждение порядка проведения открытого конкурса по отбору управляющей организации для управления многоквартирным домом?","o":["Правительство Российской Федерации","уполномоченный исполнительный орган субъекта Российской Федерации","орган местного самоуправления"],"a":[0],"url":"https://base.garant.ru/12138291/4937220ae6cef91cd7865edfe9b471d0/","cite":"ч. 4 ст. 161 ЖК РФ","explain":"Порядок открытого конкурса по отбору УК устанавливает Правительство РФ.","review":false},{"id":129,"q":"Какие сроки установлены для предоставления управляющей организацией собственникам помещений в многоквартирном доме ежегодного отчета о выполнении договора управления многоквартирным домом?","o":["ежемесячно","ежеквартально","ежегодно"],"a":[2],"url":"https://base.garant.ru/12138291/4937220ae6cef91cd7865edfe9b471d0/","cite":"ч. 10.1 ст. 161 ЖК РФ","explain":"Отчёт представляют ежегодно за предыдущий год, в течение первого квартала текущего года.","review":false},{"id":130,"q":"Структура жилищного фонда в зависимости от формы собственности?","o":["частный и государственный жилищный фонд","частный, государственный и муниципальный жилищный фонд","частный, муниципальный, региональный и федеральный жилищный фонд"],"a":[1],"url":"https://base.garant.ru/12138291/95ef042b11da42ac166eeedeb998f688/","cite":"ч. 2 ст. 19 ЖК РФ","explain":"По форме собственности фонд делится на частный, государственный и муниципальный.","review":false},{"id":131,"q":"С какого момента у собственника помещения в многоквартирном доме возникает обязанность по оплате расходов на капитальный ремонт общего имущества собственников помещений в многоквартирном доме?","o":["с 2015 года","с момента возникновения права собственности на помещение в многоквартирном доме","с момента принятия собственниками помещений в многоквартирном доме решения о формировании фонда капитального ремонта многоквартирного дома"],"a":[1],"url":"https://base.garant.ru/12138291/a7903a0a19751770e44706bb0adac831/","cite":"ч. 3 ст. 158; ч. 3, 5.1 ст. 169 ЖК РФ","explain":"Обязанность по расходам на капремонт распространяется на собственников с возникновения права собственности. Начало начисления именно взносов зависит также от включения дома в программу и специальных сроков.","review":false},{"id":132,"q":"Каково допустимое отклонение температуры горячей воды в точке водоразбора в ночное время?","o":["не более чем на 3 °C","не более чем на 5 °C","не предусмотрено"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 5 приложения № 1; решение ВС РФ АКПИ13-394","explain":"В таблице перерасчёта указано 5 °C ночью. Это не разрешение подавать воду ниже санитарного минимума 60 °C: ВС ограничил применение нормы вопросами изменения платы. Без указания контекста вопрос двусмыслен.","review":true},{"id":133,"q":"Что понимается под государственным жилищным надзором?","o":["деятельность уполномоченных исполнительных органов субъектов Российской Федерации, определенная статьей 20 Жилищного кодекса Российской Федерации","деятельность уполномоченных органов государственной власти Российской Федерации, определенная статьей 20 Жилищного кодекса Российской Федерации, общими требованиями к организации и осуществлению государственного жилищного контроля (надзора), утвержденными постановлением Правительства Российской Федерации от 30 сентября 2021 г. № 1670","деятельность уполномоченных органов исполнительной власти субъектов Российской Федерации, направленная на предупреждение, выявление и пресечение нарушений органами государственной власти, органами местного самоуправления требований, установленных жилищным законодательством Российской Федерации"],"a":[0],"url":"https://base.garant.ru/12138291/9e3305d0d08ff111955ebd93afd10878/","cite":"ст. 20 ЖК РФ","explain":"Государственный жилищный надзор осуществляют уполномоченные исполнительные органы субъектов РФ.","review":false},{"id":134,"q":"Как определяется доля собственника помещения в многоквартирном доме в праве общей собственности на общее имущество собственников помещений в этом доме?","o":["пропорционально размеру общей площади помещения, принадлежащего собственнику","пропорционально размеру уплаченных взносов на капитальный ремонт","доли всех собственников помещений в многоквартирном доме признаются равными"],"a":[0],"url":"https://base.garant.ru/12138291/9db18ed28bd6c0256461e303941d7e7a/","cite":"ч. 1 ст. 37 ЖК РФ","explain":"Доля в общем имуществе пропорциональна общей площади принадлежащего собственнику помещения.","review":false},{"id":135,"q":"На какой период потребителю коммунальных услуг, в соответствии с Правилами предоставления субсидий на оплату жилого помещения и коммунальных услуг, утвержденными постановлением Правительства Российской Федерации от 14 декабря 2005 г. № 761, могут быть предоставлены указанные субсидии?","o":["три месяца","полгода","год"],"a":[1],"url":"https://base.garant.ru/12143735/53f89421bbdaf741eb2d1ecc4ddb4c33/","cite":"п. 41 Правил № 761","explain":"Субсидия на оплату жилья и коммунальных услуг предоставляется на шесть месяцев.","review":false},{"id":136,"q":"Будет ли начисляться потребителю коммунальных услуг плата за коммунальные услуги, предоставленные на общедомовые нужды, если объем коммунальных услуг, предоставленных за расчетный период на общедомовые нужды, составит ноль?","o":["начисляется","начисляется, в случае если собственниками помещений в многоквартирном доме принято соответствующее решение","не начисляется"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 45 Правил № 354","explain":"Если определённый объём коммунальной услуги на общедомовые нужды равен нулю, плата за этот объём не начисляется.","review":false},{"id":137,"q":"В каких случаях не производится перерасчет размера платы за предоставленную потребителю в жилом помещении коммунальную услугу (за исключением коммунальных услуг по отоплению, электроснабжению и газоснабжению на цели отопления жилых помещений)?","o":["в случае оборудования жилого помещения индивидуальными или общими (квартирными) приборами учета коммунальных ресурсов","в случае отсутствия в жилом помещении индивидуальных или общих (квартирных) приборов учета коммунальных ресурсов при наличии технической возможности установки таких приборов","в случае отсутствия индивидуальных или общих (квартирных) приборов учета в связи с отсутствием технической возможности установки таких приборов"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 86 Правил № 354","explain":"При временном отсутствии перерасчёт по общему правилу не выполняют, если счётчика нет при наличии технической возможности его установки. Есть специальные исключения; вопрос не указывает, что речь об отсутствии.","review":false},{"id":138,"q":"В каком размере исполнителем коммунальных услуг возмещается вред, причиненный жизни, здоровью или имуществу потребителя коммунальных услуг вследствие нарушения качества предоставления коммунальных услуг или вследствие непредоставления потребителю коммунальных услуг полной и достоверной информации о предоставляемых коммунальных услугах?","o":["в двукратном размере при наличии вины исполнителя","в полном объеме независимо от вины исполнителя","в полном объеме при наличии вины исполнителя"],"a":[1],"url":"https://base.garant.ru/10106035/888134b28b1397ffae87a0ab1e117954/","cite":"п. 151 Правил № 354; ст. 14 Закона о защите прав потребителей","explain":"Вред жизни, здоровью и имуществу из-за ненадлежащих услуг или информации возмещается в полном объёме независимо от вины с предусмотренными законом исключениями.","review":false},{"id":139,"q":"Какой метод определения нормативов потребления коммунальных ресурсов в целях содержания общего имущества собственников помещений в многоквартирном доме является приоритетным?","o":["нормативный метод","метод аналогов","расчетный метод"],"a":[1],"url":"https://base.garant.ru/58164038/","cite":"пп. 21–22 Правил № 306","explain":"Приоритетен метод аналогов; расчётный метод используют при невозможности применения данных аналогов в предусмотренных случаях.","review":false},{"id":140,"q":"Что входит в структуру платы за жилое помещение и коммунальные услуги для собственника помещения в многоквартирном доме?","o":["плата за содержание жилого помещения и взнос на капитальный ремонт","плата за содержание жилого помещения, включающая в себя плату за услуги, работы по управлению многоквартирным домом, за содержание и текущий ремонт общего имущества в многоквартирном доме, за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества в многоквартирном доме, и плата за коммунальные услуги","плата за содержание жилого помещения, включающая в себя плату за услуги, работы по управлению многоквартирным домом, за содержание и текущий ремонт общего имущества в многоквартирном доме, за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества в многоквартирном доме, взнос на капитальный ремонт, плата за коммунальные услуги"],"a":[2],"url":"https://base.garant.ru/12138291/055d1b82a84145ca60b96f2b0fee8ae8/","cite":"ч. 2 ст. 154 ЖК РФ","explain":"Собственник оплачивает содержание жилья, взнос на капремонт и коммунальные услуги.","review":false},{"id":141,"q":"Какие лица в управляющей организации несут персональную ответственность за соблюдение требований пожарной безопасности в многоквартирном доме?","o":["руководитель управляющей организации","любой сотрудник управляющей организации","должностные лица управляющей организации не несут персональную ответственность за соблюдение требований пожарной безопасности"],"a":[0],"url":"https://base.garant.ru/10103955/31c8140a2e1dc585c5111b6d2281821d/","cite":"ст. 37–38 Закона № 69-ФЗ","explain":"Руководитель отвечает за выполнение требований пожарной безопасности в пределах компетенции организации. Могут отвечать также назначенные ответственные лица и другие субъекты.","review":false},{"id":142,"q":"В какой период календарного года проводится промывка систем отопления в многоквартирном доме?","o":["ежегодно после окончания отопительного периода","ежегодно в период отключения отопления","ежегодно перед отопительным периодом"],"a":[0],"url":"https://base.garant.ru/12132859/","cite":"п. 5.2.10 Правил № 170","explain":"Промывка систем теплопотребления производится ежегодно после окончания отопительного периода, а также после предусмотренных ремонтов и монтажа.","review":false},{"id":143,"q":"Какие сроки установлены для восстановления управляющей организацией документов, входящих в состав технической документации на многоквартирный дом?","o":["один месяц","три месяца","срок определяется решением общего собрания собственников помещений в многоквартирном доме"],"a":[1],"url":"https://base.garant.ru/70379374/","cite":"п. 21 Правил № 416","explain":"При передаче управления отсутствующие документы восстанавливают в течение трёх месяцев со дня получения уведомления, предусмотренного п. 18.","review":false},{"id":144,"q":"Какие работы по обеспечению требований пожарной безопасности предусмотрены минимальным перечнем услуг и работ, необходимых для обеспечения надлежащего содержания общего имущества в многоквартирном доме, утвержденным постановлением Правительства Российской Федерации от 3 апреля 2013 г. № 290?","o":["осмотры и обеспечение работоспособного состояния мест общего пользования в многоквартирном доме","осмотры и обеспечение работоспособного состояния пожарных лестниц, лазов, проходов, выходов, систем аварийного освещения, пожаротушения, сигнализации, противопожарного водоснабжения, средств противопожарной защиты, противодымной защиты","осмотры и обеспечение работоспособного состояния пожарных лестниц, лазов, проходов, выходов, систем аварийного освещения, пожаротушения, сигнализации, противопожарного водоснабжения, средств противопожарной защиты, противодымной защиты, а также монтаж, техническое обслуживание и ремонт средств обеспечения пожарной безопасности зданий и сооружений"],"a":[1],"url":"https://base.garant.ru/76819177/","cite":"п. 27 Минимального перечня № 290","explain":"Дословный перечень — осмотры и обеспечение работоспособности перечисленных противопожарных элементов и систем, как в варианте 2.","review":false},{"id":145,"q":"Какие обязательные расходы несет собственник помещения в многоквартирном доме в отношении общего имущества собственников помещений в многоквартирном доме?","o":["расходы на содержание и текущий ремонт общего имущества в многоквартирном доме","расходы по оплате за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества в многоквартирном доме","расходы на содержание и текущий ремонт общего имущества в многоквартирном доме, расходы по оплате за коммунальные ресурсы, потребляемые при использовании и содержании общего имущества в многоквартирном доме"],"a":[2],"url":"https://base.garant.ru/12138291/055d1b82a84145ca60b96f2b0fee8ae8/","cite":"п. 1 ч. 2 ст. 154; ст. 39 ЖК РФ","explain":"Обе группы расходов относятся к содержанию общего имущества. Вопрос не охватывает все обязанности собственника, в частности взнос на капремонт.","review":false},{"id":146,"q":"В каких случаях собственники помещений в многоквартирном доме вправе принимать решения об изменении способа управления многоквартирным домом?","o":["если управляющая организация не выполняет условия договора управления многоквартирным домом","случаи устанавливаются уполномоченным органом государственной власти субъекта Российской Федерации","случаи законодательством Российской Федерации не предусмотрены"],"a":[],"url":"https://base.garant.ru/12138291/4937220ae6cef91cd7865edfe9b471d0/","cite":"ч. 3 ст. 161 ЖК РФ","explain":"Собственники могут выбрать и изменить способ управления в любое время решением собрания. Ни один вариант не передаёт это правило. Неисполнение УК договора — основание для отдельного вопроса об отказе от договора по ч. 8.2 ст. 162.","review":true},{"id":147,"q":"Обязаны ли собственники помещений в многоквартирном доме, не принимавшие участие в общем собрании собственников помещений в данном доме, исполнять решения, принятые на таком собрании?","o":["обязаны","обязаны, если собственниками помещений в многоквартирном доме принято решение об определении обязанности по исполнению решений собственников помещений","не обязаны"],"a":[0],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 5 ст. 46 ЖК РФ","explain":"Законное решение собрания по вопросам его компетенции обязательно для всех собственников, включая не участвовавших в голосовании.","review":false},{"id":148,"q":"Состав обязательного перечня услуг и (или) работ по капитальному ремонту общего имущества собственников помещений в многоквартирном доме, устанавливаемый нормативным правовым актом субъекта Российской Федерации?","o":["ремонт внутридомовых инженерных систем электро-, тепло-, газо-, водоснабжения, водоотведения; ремонт, замена, модернизация лифтов, ремонт лифтовых шахт, машинных и блочных помещений; ремонт крыши; ремонт фасада; ремонт фундамента многоквартирного дома","ремонт внутридомовых инженерных систем электро-, тепло-, газо-, водоснабжения, водоотведения; ремонт, замена, модернизация лифтов, ремонт лифтовых шахт, машинных и блочных помещений; ремонт крыши; ремонт подвальных помещений, относящихся к общему имуществу в многоквартирном доме; ремонт фасада; ремонт фундамента многоквартирного дома","обязательный перечень услуг и (или) работ по капитальному ремонту общего имущества собственников помещений в многоквартирном доме не устанавливается"],"a":[1],"url":"https://base.garant.ru/12138291/2779232b3b7e6fd9fea197b64b6001e4/","cite":"ч. 1 ст. 166 ЖК РФ","explain":"В федеральном перечне есть и ремонт подвалов, относящихся к общему имуществу. Вариант 1 их пропускает.","review":false},{"id":149,"q":"Каковы параметры допустимого отклонения давления в системе холодного водоснабжения в многоквартирном доме?","o":["от 0,03 МПа до 0,6 МПа","от 0,6 МПа до 1 МПа","отклонение давления не допускается"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 3 приложения № 1 к Правилам № 354","explain":"Отклонение давления от установленного диапазона не допускается. Вариант 1 описывает сам диапазон, а не допустимое отклонение.","review":false},{"id":150,"q":"Какова суммарная продолжительность допустимого перерыва в подаче холодной воды в многоквартирном доме в течение месяца?","o":["4 часа, за исключением случаев аварии в централизованных сетях инженерно-технического обеспечения холодного водоснабжения","8 часов, за исключением случаев аварии в централизованных сетях инженерно-технического обеспечения холодного водоснабжения","16 часов, за исключением случаев аварии в централизованных сетях инженерно-технического обеспечения холодного водоснабжения"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 1 приложения № 1 к Правилам № 354","explain":"Общий суммарный предел перерыва ХВС — восемь часов в течение месяца; единовременный предел и аварии регулируются отдельно.","review":false},{"id":151,"q":"Осуществляется ли перерасчет размера платы за коммунальную услугу по водоотведению в случае произведения перерасчета размера платы за коммунальную услугу по холодному водоснабжению и (или) горячему водоснабжению?","o":["осуществляется","осуществляется, в случае заключения договора ресурсоснабжения между исполнителем коммунальных услуг и ресурсоснабжающей организацией","не осуществляется"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 87 Правил № 354","explain":"Перерасчёт водоотведения выполняют при перерасчёте ХВС и/или ГВС в предусмотренных правилами случаях.","review":false},{"id":152,"q":"Каким федеральным законом (федеральными законами) регулируются отношения в сфере теплоснабжения?","o":["Федеральный закон от 21 июля 2005 г. № 115-ФЗ «О концессионных соглашениях»","Федеральный закон от 27 июля 2010 г. № 190-ФЗ «О теплоснабжении»","Федеральные законы от 21 июля 2005 г. № 115-ФЗ «О концессионных соглашениях» и от 27 июля 2010 г. № 190-ФЗ «О теплоснабжении»"],"a":[1],"url":"https://base.garant.ru/12177489/1cafb24d049dcd1e7707a22d98e9858f/","cite":"ст. 1–2 Закона № 190-ФЗ","explain":"Специальный закон, регулирующий отношения в сфере теплоснабжения, — № 190-ФЗ. Закон о концессиях регулирует отдельные договорные механизмы.","review":false},{"id":153,"q":"Является ли обращение собственников помещений в многоквартирном доме основанием для проведения уполномоченным исполнительным органом субъекта Российской Федерации, осуществляющим государственный жилищный надзор, внеплановой проверки в части обоснованности начисления размера платы за коммунальные услуги в отношении ресурсоснабжающей организации, заключившей с каждым собственником помещения в многоквартирном доме договор, содержащий положения о предоставлении коммунальных услуг?","o":["является","не является, поскольку необходимо обращаться в орган государственного жилищного надзора посредством государственной информационной системы жилищно-коммунального хозяйства","не является, поскольку указанное основание не предусмотрено для проведения внеплановых проверок"],"a":[0],"url":"https://base.garant.ru/12138291/9e3305d0d08ff111955ebd93afd10878/","cite":"ст. 20 ЖК РФ; Закон № 248-ФЗ","explain":"Обращение о нарушении начислений может служить основанием для контрольного реагирования после оценки сведений и соблюдения процедуры. Не каждое обращение автоматически означает выездную проверку.","review":false},{"id":154,"q":"В чьи обязанности входит информирование собственников помещений в многоквартирных домах о поступивших предложениях по оснащению многоквартирных домов, помещений в них приборами учета коммунальных ресурсов, а также о сроках их оснащения приборами учета используемых коммунальных ресурсов?","o":["лицо, ответственное за содержание многоквартирного дома","ресурсоснабжающая организация","уполномоченный исполнительный орган субъекта Российской Федерации, осуществляющий государственный жилищный надзор"],"a":[0],"url":"https://base.garant.ru/12171109/b6e02e45ca70d110df0019b9fe339c70/","cite":"ч. 7 ст. 13 Закона № 261-ФЗ","explain":"Информирование собственников о предложениях по оснащению приборами учёта обеспечивает лицо, ответственное за содержание дома.","review":false},{"id":155,"q":"Какая мера административной ответственности предусмотрена для должностных лиц организаций, осуществляющих управление многоквартирными домами, за неразмещение в соответствии с законодательством Российской Федерации о государственной информационной системе жилищно-коммунального хозяйства информации в государственной информационной системе жилищно-коммунального хозяйства?","o":["предупреждение или административный штраф в размере от пяти тысяч до десяти тысяч рублей","административный штраф в размере от пяти тысяч до десяти тысяч рублей","административный штраф в размере от пяти тысяч до десяти тысяч рублей или дисквалификация на срок от одного года до трех лет"],"a":[0],"url":"https://base.garant.ru/12125267/63957ac118119463f8081d0003102bec/","cite":"ч. 2 ст. 13.19.2 КоАП РФ","explain":"При первичном нарушении для должностных лиц предусмотрены предупреждение или штраф 5–10 тыс. руб.; повторность регулируется отдельно.","review":false},{"id":156,"q":"Какой размер аванса за проведение работ и услуг по капитальному ремонту общего имущества собственников помещений в многоквартирном доме вправе уплачивать региональный оператор?","o":["не более чем десять процентов от стоимости соответствующего вида услуг и (или) работ по капитальному ремонту","не более чем тридцать процентов от стоимости соответствующего вида услуг и (или) работ по капитальному ремонту","не более чем пятьдесят процентов от стоимости соответствующего вида услуг и (или) работ по капитальному ремонту"],"a":[1],"url":"https://base.garant.ru/12138291/5434a9dc4ceb5e696a30fe12e328d51d/","cite":"ч. 3–3.1 ст. 190 ЖК РФ","explain":"Общий предел аванса регионального оператора — 30%. Для специальных случаев законом предусмотрены исключения.","review":false},{"id":157,"q":"Какова нормативная температура воздуха в жилых помещениях в многоквартирном доме (за исключением угловых комнат, а также за исключением районов с температурой наиболее холодной пятидневки -31 °C и ниже)?","o":["18 °C","20 °C","22 °C"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 15 приложения № 1 к Правилам № 354","explain":"Для указанной в вопросе обычной жилой комнаты норматив — не ниже +18 °C. Угловые комнаты и особо холодные районы имеют другие значения.","review":false},{"id":158,"q":"Каково допустимое давление во внутридомовой системе отопления с чугунными радиаторами?","o":["не более 0,3 МПа (3 кгс/кв. см)","не более 0,6 МПа (6 кгс/кв. см)","не более 0,8 МПа (8 кгс/кв. см)"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 16 приложения № 1 к Правилам № 354","explain":"В системе с чугунными радиаторами давление — не более 0,6 МПа (6 кгс/см²).","review":false},{"id":159,"q":"Допускается ли отклонение давления во внутридомовой системе отопления от нормативных значений?","o":["допускается не более, чем на 0,0001 МПа","допускается не более, чем на 0,0005 МПа","не допускается"],"a":[2],"url":"https://base.garant.ru/12186043/","cite":"п. 16 приложения № 1 к Правилам № 354","explain":"Отклонение давления в системе отопления от установленных значений не допускается.","review":false},{"id":160,"q":"Допускается ли перерывы в предоставлении услуги по отоплению в жилых помещениях в отопительный период?","o":["допускается не более, чем на 8 часов (суммарно) в течение одного месяца","допускается не более, чем на 24 часа (суммарно) в течение одного месяца","не допускается"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 14 приложения № 1 к Правилам № 354","explain":"Допускается не более 24 часов перерыва суммарно за месяц, при этом действуют более короткие единовременные пределы в зависимости от температуры.","review":false},{"id":161,"q":"Виды жилых помещений специализированного жилищного фонда?","o":["служебные жилые помещения, жилые помещения в общежитиях, жилые помещения маневренного фонда, жилые помещения фонда для временного поселения вынужденных переселенцев, жилые помещения для социальной защиты отдельных категорий граждан, жилые помещения для детей-сирот и детей, оставшихся без попечения родителей, лиц из числа детей-сирот и детей, оставшихся без попечения родителей","служебные жилые помещения, жилые помещения маневренного фонда, жилые помещения в домах системы социального обслуживания граждан, жилые помещения фонда для временного поселения лиц, признанных беженцами, жилые помещения для социальной защиты отдельных категорий граждан, жилые помещения для детей-сирот и детей, оставшихся без попечения родителей, лиц из числа детей-сирот и детей, оставшихся без попечения родителей","служебные жилые помещения, жилые помещения в общежитиях, жилые помещения маневренного фонда, жилые помещения в домах системы социального обслуживания граждан, жилые помещения фонда для временного поселения вынужденных переселенцев, жилые помещения фонда для временного поселения лиц, признанных беженцами, жилые помещения для социальной защиты отдельных категорий граждан, жилые помещения для детей-сирот и детей, оставшихся без попечения родителей, лиц из числа детей-сирот и детей, оставшихся без попечения родителей"],"a":[2],"url":"https://base.garant.ru/12138291/a01fd19fbf2aae1b9a36f043855d0c20/","cite":"ч. 1 ст. 92 ЖК РФ","explain":"Вариант 3 объединяет все перечисленные категории специализированного жилищного фонда.","review":false},{"id":162,"q":"Каково допустимое отклонение температуры горячей воды в точке водоразбора от температуры горячей воды в точке водозабора, соответствующей требованиям законодательства Российской Федерации о техническом регулировании, в дневное время в многоквартирном доме?","o":["не более чем на 2 °C","не более чем на 3 °C","не более чем на 5 °C"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 5 приложения № 1; решение ВС РФ АКПИ13-394","explain":"В таблице перерасчёта указано 3 °C днём. В вопросе ошибочно сопоставлены водоразбор и водозабор; отклонение не отменяет санитарные 60–75 °C. В таком виде вопрос требует уточнения.","review":true},{"id":163,"q":"Допустимое давление в системе горячего водоснабжения в точке разбора в многоквартирном доме?","o":["от 0,01 МПа до 0,30 МПа","от 0,03 МПа до 0,45 МПа","от 0,04 МПа до 0,45 МПа"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"п. 7 приложения № 1 к Правилам № 354","explain":"Давление горячей воды в точке разбора — 0,03–0,45 МПа.","review":false},{"id":164,"q":"Как определяется размер платы за коммунальные услуги за расчетный период?","o":["исходя из объема потребляемых коммунальных услуг при наличии приборов учета коммунальных ресурсов","исходя из нормативов потребления коммунальных услуг при отсутствии приборов учета","исходя из объема потребляемых коммунальных услуг при наличии приборов учета коммунальных ресурсов и исходя из нормативов потребления коммунальных услуг при отсутствии приборов учета"],"a":[2],"url":"https://base.garant.ru/12138291/87ed542564909a7be0ffb87814354e5b/","cite":"ч. 1 ст. 157 ЖК РФ; Правила № 354","explain":"Общее правило: расчёт по объёму показаний приборов, а при их отсутствии — по нормативам, с предусмотренными исключениями.","review":false},{"id":165,"q":"Нормативная температура горячей воды в точке водоразбора в многоквартирном доме?","o":["не ниже 50 °C и не выше 75 °C","не ниже 60 °C и не выше 75 °C","не ниже 75 °C и не выше 85 °C"],"a":[1],"url":"https://base.garant.ru/400289764/","cite":"п. 84 СанПиН 2.1.3684-21","explain":"Температура горячей воды в точках водоразбора — не ниже 60 °C и не выше 75 °C.","review":false},{"id":166,"q":"Какова периодичность проведения текущего осмотра состояния дымовых и вентиляционных каналов и их очистки в процессе эксплуатации дымовых и вентиляционных каналов?","o":["не реже тех раз в год (в период с августа по сентябрь, с декабря по февраль, с марта по май)","не реже одного раза в год (при подготовке жилищного фонда к осенне-зимнему периоду)","по мере необходимости"],"a":[0],"url":"https://base.garant.ru/70381684/","cite":"подп. «в» п. 12 Правил № 410","explain":"Периодическая проверка каналов — не реже трёх раз в год: август–сентябрь, декабрь–февраль, март–май. Очистку выполняют при необходимости по результатам проверки.","review":false},{"id":167,"q":"На каких основаниях осуществляется подключение (технологическое присоединение) к системам инженерно-технического обеспечения?","o":["наличие технической возможности подключения (технологического присоединения) к системе инженерно-технического обеспечения, наличие свободной мощности в соответствующей точке подключения (технологического присоединения)","наличие технической возможности подключения (технологического присоединения) к системе инженерно-технического обеспечения, наличие свободной мощности в соответствующей точке подключения (технологического присоединения), заключение договора на подключение (технологическое присоединение) объекта","основания не предусмотрены"],"a":[1],"url":"https://www.consultant.ru/document/cons_doc_LAW_51040/38b3f131482e11c9beba5511be5d68625d177d69/","cite":"ст. 52.1 ГрК РФ; отраслевые правила подключения","explain":"Технологическое присоединение осуществляется на договорной основе с учётом технической возможности и условий отраслевых правил. При нехватке мощности возможны специальные процедуры, поэтому вариант упрощён.","review":false},{"id":168,"q":"С какой периодичностью осуществляется техническое обслуживание внутридомового и внутриквартирного газового оборудования?","o":["не реже трех раз в год","не реже одного раза в год","периодичность предусмотрена договором о техническом обслуживании и ремонте внутридомового и (или) внутриквартирного газового оборудования"],"a":[1],"url":"https://base.garant.ru/70381684/","cite":"п. 43 Правил № 410","explain":"Техническое обслуживание газового оборудования проводится не реже одного раза в год, если отдельные операции не требуют иной частоты.","review":false},{"id":169,"q":"В чьи обязанности входит проведение мероприятий, направленных на регулирование расхода тепловой энергии в многоквартирном доме в целях ее сбережения в отопительный сезон?","o":["лицо, ответственное за содержание многоквартирного дома","ресурсоснабжающая организация","собственники помещений в многоквартирном доме"],"a":[0],"url":"https://base.garant.ru/12171109/b6e02e45ca70d110df0019b9fe339c70/","cite":"ч. 8 ст. 12 Закона № 261-ФЗ","explain":"Регулировать расход тепла обязано лицо, ответственное за содержание дома, при технической возможности и соблюдении качества услуг.","review":false},{"id":170,"q":"За сколько дней до приостановления в одностороннем порядке исполнения обязательств по поставке газа в случаях, предусмотренных Правилами поставки газа для обеспечения коммунально-бытовых нужд граждан, утвержденными постановлением № 549, поставщик газа обязан предварительно письменно уведомить абонента?","o":["не позднее чем за 10 календарных дней","не позднее чем за 20 календарных дней","не позднее чем за 30 календарных дней"],"a":[1],"url":"https://base.garant.ru/12161689/","cite":"п. 46 Правил № 549","explain":"При предусмотренном этим пунктом приостановлении абонента письменно уведомляют не позднее чем за 20 календарных дней. Аварийные отключения регулируются отдельно.","review":false},{"id":171,"q":"Как определятся плата за содержание жилого помещения за расчетный период?","o":["исходя из площади жилого помещения","исходя из количества зарегистрированных граждан","исходя из количества проживающих граждан"],"a":[0],"url":"https://base.garant.ru/12138291/a7903a0a19751770e44706bb0adac831/","cite":"ч. 1 ст. 158; ч. 1 ст. 37 ЖК РФ","explain":"Расходы распределяются соразмерно доле в общем имуществе, то есть пропорционально площади помещения.","review":false},{"id":172,"q":"Установлены ли специальные требования для измерения температуры воздуха в жилых помещениях?","o":["установлены, осуществляется в комнате (при наличии нескольких комнат - в наибольшей по площади жилой комнате), в центре плоскостей, отстоящих от внутренней поверхности наружной стены и обогревающего элемента на 1 м и в центре помещения (точке пересечения диагональных линий помещения) на высоте 0,5 м","установлены, осуществляется в комнате (при наличии нескольких комнат - в наибольшей по площади жилой комнате), в центре плоскостей, отстоящих от внутренней поверхности наружной стены и обогревающего элемента на 0,5 м и в центре помещения (точке пересечения диагональных линий помещения) на высоте 1 м","не установлены"],"a":[1],"url":"https://base.garant.ru/12186043/","cite":"сноска 7 к приложению № 1 Правил № 354","explain":"Указаны 0,5 м от наружной стены и отопительного прибора и высота 1 м; измеряют также в центре помещения.","review":false},{"id":173,"q":"Какие действия обязан осуществить исполнитель коммунальных услуг после устранения причин нарушения качества коммунальной услуги?","o":["удостовериться в том, что потребителю предоставляется коммунальная услуга надлежащего качества в необходимом объеме и составить акт о результатах проверки по итогам устранения причин нарушения качества коммунальной услуги","составить акт о предоставлении коммунальной услуги надлежащего качества в необходимом объеме","исполнитель не обязан осуществить никаких действий после устранения причин нарушения качества коммунальной услуги"],"a":[0],"url":"https://base.garant.ru/12186043/","cite":"п. 113 Правил № 354","explain":"Исполнитель проверяет восстановление качества; в предусмотренном пунктом случае проводит проверку у потребителя и составляет акт.","review":false},{"id":174,"q":"С какого момента исполнителем коммунальных услуг начисляются пени лицам, имеющим задолженность по плате за жилое помещение и коммунальные услуги?","o":["со дня, следующего за днем наступления установленного срока оплаты","с тридцать первого дня, следующего за днем наступления установленного срока оплаты","с девяносто первого дня, следующего за днем наступления установленного срока оплаты"],"a":[1],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 14 ст. 155 ЖК РФ","explain":"По общему правилу пеня начинается с 31-го дня после установленного срока оплаты; применяются также специальные исключения.","review":false},{"id":175,"q":"Вправе ли исполнитель коммунальных услуг привлекать иных лиц в целях оказания услуг по начислению платы за жилое помещение и коммунальные услуги?","o":["вправе","вправе, если собственниками помещений в многоквартирном доме принято соответствующее решение","не вправе"],"a":[0],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 15 ст. 155 ЖК РФ","explain":"Получатель платы вправе привлекать представителей для расчётов и взимания платы в установленном законом порядке.","review":false},{"id":176,"q":"В чьи обязанности входит предоставление в уполномоченный исполнительный орган субъекта Российской Федерации, осуществляющий государственный жилищный надзор, подлинников решений и протокола общего собрания собственников помещений в многоквартирном доме?","o":["председатель совета многоквартирного дома","управляющая организация, правление товарищества собственников жилья, жилищного или жилищно-строительного кооператива, иного специализированного потребительского кооператива, лицо, по инициативе которого было созвано общее собрание собственников помещений в многоквартирном доме","лицо, по инициативе которого было созвано общее собрание собственников помещений в многоквартирном доме"],"a":[1],"url":"https://base.garant.ru/12138291/363aa18e6c32ff15fa5ec3b09cbefbf6/","cite":"ч. 1–1.1 ст. 46 ЖК РФ","explain":"Обычно подлинники в ГЖИ направляет УК/правление после получения от инициатора; при непосредственном управлении — сам инициатор. Вариант 2 объединяет этих субъектов, но не означает одновременную обязанность всех.","review":false},{"id":177,"q":"С использованием какой информационной системы осуществляется раскрытие информации организациями, осуществляющими деятельность в сфере управления многоквартирными домами?","o":["единый информационный портал «Реформа ЖКХ»","государственная информационная система жилищно-коммунального хозяйства","официальный сайт Министерства строительства и жилищно-коммунального хозяйства Российской Федерации в информационно-телекоммуникационной сети «Интернет»"],"a":[1],"url":"https://base.garant.ru/12138291/4937220ae6cef91cd7865edfe9b471d0/","cite":"ч. 10.1 ст. 161 ЖК РФ","explain":"Обязательная информация о деятельности по управлению размещается в ГИС ЖКХ.","review":false},{"id":178,"q":"Назначение жилых помещений в общежитиях?","o":["проживание граждан в период их работы или обучения","временное проживание граждан в период их работы, службы или обучения","проживание граждан в связи с характером их трудовых отношений с органом государственной власти, органом местного самоуправления, государственным или муниципальным унитарным предприятием, государственным или муниципальным учреждением, в связи с прохождением службы, в связи с назначением на государственную должность Российской Федерации или государственную должность субъекта Российской Федерации либо в связи с избранием на выборные должности в органы государственной власти или органы местного самоуправления"],"a":[1],"url":"https://base.garant.ru/12138291/d31bd2d89fd17d70aaefe3134ccf3ea8/","cite":"ч. 1 ст. 94 ЖК РФ","explain":"Общежития предназначены для временного проживания в период работы, службы или обучения.","review":false},{"id":179,"q":"В чьи обязанности входит обеспечение выполнения работ в целях надлежащего содержания систем внутридомового газового оборудования, лифтового хозяйства и противопожарных систем многоквартирного дома?","o":["собственники помещений в многоквартирном доме","лица, ответственные за обслуживание общего имущества в многоквартирном доме","лица, ответственные за содержание и ремонт общего имущества в многоквартирном доме"],"a":[2],"url":"https://base.garant.ru/76819177/","cite":"п. 8 Правил оказания услуг № 290","explain":"Работы по ВДГО, лифтам и противопожарным системам обеспечивает лицо, ответственное за содержание и ремонт общего имущества, привлекая надлежащих исполнителей.","review":false},{"id":180,"q":"Что понимается под классом энергетической эффективности в многоквартирном доме?","o":["характеристики, отражающие отношение полезного эффекта от использования энергетических ресурсов к затратам энергетических ресурсов, произведенным в целях получения такого эффекта, применительно к продукции, технологическому процессу, юридическому лицу, индивидуальному предпринимателю","характеристика продукции, отражающая ее энергетическую эффективность","сбор и обработка информации об использовании энергетических ресурсов в целях получения достоверной информации об объеме используемых энергетических ресурсов, о показателях энергетической эффективности, выявления возможностей энергосбережения и повышения энергетической эффективности с отражением полученных результатов в энергетическом паспорте"],"a":[1],"url":"https://base.garant.ru/12171109/741609f9002bd54a24e5c49cb5af953b/","cite":"п. 5 ст. 2 Закона № 261-ФЗ","explain":"Класс энергетической эффективности — характеристика продукции, отражающая её энергетическую эффективность. Для домов порядок присвоения класса установлен специальными нормами.","review":false},{"id":181,"q":"Каким документом оформляется передача технической документации на многоквартирный дом и иных связанных с управлением этим домом документов?","o":["акт приема-передачи технической документации на многоквартирный дом","протокол приема технической документации на многоквартирный дом","передача технической документации на многоквартирный дом отдельным документом не оформляется"],"a":[0],"url":"https://base.garant.ru/70379374/","cite":"пп. 21–23 Правил № 416","explain":"Документацию и оборудование передают по акту приёма-передачи, отражая состав и разногласия.","review":false},{"id":182,"q":"Кто может быть владельцем специального счета, предназначенного для перечисления денежных средств фонда капитального ремонта общего имущества собственников помещений в многоквартирном доме?","o":["региональный оператор","товарищество собственников жилья, жилищный кооператив, управляющая организация","товарищество собственников жилья, жилищный кооператив, управляющая организация, региональный оператор"],"a":[2],"url":"https://base.garant.ru/12138291/be812b7279e10413ff6e1603f421d2e0/","cite":"ч. 2–3 ст. 175 ЖК РФ","explain":"Владельцем спецсчёта могут быть ТСЖ, кооператив, УК, а также региональный оператор при соблюдении условий закона.","review":false},{"id":183,"q":"С какой периодичностью ресурсоснабжающая организация обязана информировать потребителей коммунальных услуг о состоянии расчетов исполнителя коммунальных услуг за поставленный в многоквартирный дом коммунальный ресурс по соответствующему договору ресурсоснабжения?","o":["не чаще одного раза в месяц, в случае, если данное условие предусмотрено в договоре ресурсоснабжения","не реже одного раза в месяц","не реже одного раза в год"],"a":[0],"url":"https://base.garant.ru/70139750/","cite":"п. 28 Правил № 124","explain":"Предусмотрено право РСО информировать потребителей, если оно закреплено договором, не чаще одного раза в месяц — вариант 1. Вопрос ошибочно спрашивает об обязанности, а варианты 2–3 переворачивают ограничение частоты.","review":true},{"id":184,"q":"Кем определяется класс энергетической эффективности многоквартирного дома, построенного, реконструированного или прошедшего капитальный ремонт и вводимого в эксплуатацию?","o":["уполномоченный исполнительный орган субъекта Российской Федерации","орган государственного строительного надзора","товарищество собственников жилья, жилищный или жилищно-строительный кооператив, управляющая организация"],"a":[1],"url":"https://base.garant.ru/12171109/b6e02e45ca70d110df0019b9fe339c70/","cite":"ч. 1 ст. 12 Закона № 261-ФЗ","explain":"Класс вводимого в эксплуатацию МКД определяет орган государственного строительного надзора. Для эксплуатируемых домов действует иной порядок.","review":false},{"id":185,"q":"Какая периодичность установлена для информирования уполномоченным органом, осуществляющим государственный жилищный надзор, населения о лицах, ответственных за содержание многоквартирных домов и подвергнутых административному наказанию за нарушение установленных требований к проведению мероприятий по энергосбережению и повышению энергетической эффективности, по результатам проведенных проверок соблюдения правил содержания общего имущества собственников помещений в многоквартирном доме?","o":["не реже чем один раз в месяц","не реже чем один раз в год","не чаще чем один раз в год"],"a":[1],"url":"https://base.garant.ru/12171109/b6e02e45ca70d110df0019b9fe339c70/","cite":"ч. 9 ст. 12 Закона № 261-ФЗ","explain":"Информацию о привлечённых к ответственности за нарушения энергосбережения публикуют не реже одного раза в год.","review":false},{"id":186,"q":"Основания для включения сведений об организации, осуществляющей деятельность по управлению многоквартирным домом, в реестр дисквалифицированных лиц?","o":["аннулирование лицензии индивидуального предпринимателя на осуществление деятельности по управлению многоквартирными домами","применение в отношении должностного лица управляющей организации, на которого возложена ответственность за соблюдение требований к обеспечению надлежащего содержания общего имущества в многоквартирном доме, административного наказания в виде дисквалификации","аннулирование лицензии индивидуального предпринимателя на осуществление деятельности по управлению многоквартирными домами, применение в отношении должностного лица управляющей организации, на которого возложена ответственность за соблюдение требований к обеспечению надлежащего содержания общего имущества в многоквартирном доме, административного наказания в виде дисквалификации"],"a":[2],"url":"https://base.garant.ru/12138291/9ab581f332f422774f6e67652ce80a1c/","cite":"п. 4 ч. 1 ст. 193; ст. 195 ЖК РФ","explain":"Вариант 3 охватывает аннулирование лицензии ИП и дисквалификацию ответственного лица. Реестр содержит сведения о физических лицах, а вопрос ошибочно говорит о включении организации.","review":true},{"id":187,"q":"Какие меры административной ответственности установлены для лиц, виновных в нарушении законодательства Российской Федерации об энергосбережении и о повышении энергетической эффективности?","o":["предупреждение и административный штраф на должностных лиц в размере от пяти тысяч до десяти тысяч рублей, на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до пятнадцати тысяч рублей, на юридических лиц - от двадцати тысяч до тридцати тысяч рублей","административный штраф на должностных лиц в размере от пяти тысяч до десяти тысяч рублей, на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от десяти тысяч до пятнадцати тысяч рублей, на юридических лиц - от двадцати тысяч до тридцати тысяч рублей","административный штраф на должностных лиц в размере от двадцати тысяч до тридцати тысяч рублей; на юридических лиц - от ста тысяч до ста пятидесяти тысяч рублей"],"a":[1],"url":"https://base.garant.ru/12125267/147497dcdec591c43b95d63b55240196/","cite":"ч. 4–5 ст. 9.16 КоАП РФ","explain":"Вариант 2 соответствует отдельным нарушениям требований энергосбережения при содержании МКД. Но статья содержит разные составы и санкции; вопрос не указывает конкретный состав и потому не имеет универсального размера штрафа.","review":true},{"id":188,"q":"Какими нормативными правовыми актами Российской Федерации регулируется порядок проведения капитального ремонта общего имущества собственников помещений в многоквартирных домах?","o":["Жилищный кодекс Российской Федерации","нормативные правовые акты субъектов Российской Федерации","Жилищный кодекс Российской Федерации, нормативные правовые акты субъектов Российской Федерации"],"a":[2],"url":"https://base.garant.ru/12138291/2779232b3b7e6fd9fea197b64b6001e4/","cite":"раздел IX ЖК РФ и законодательство субъекта РФ","explain":"Порядок капитального ремонта регулируют ЖК РФ и принятые в его рамках региональные нормативные акты.","review":false},{"id":189,"q":"Необходимо ли наличие решения общего собрания собственников помещений в многоквартирном доме для предоставления им коммунальных услуг ресурсоснабжающей организацией, региональным оператором по обращению с твердыми коммунальными отходами в соответствии с пунктом 2 части 1 и частью 2 статьи 157 2 Жилищного кодекса Российской Федерации?","o":["необходимо","необходимо, если иное не предусмотрено договором ресурсоснабжения","необходимость отсутствует"],"a":[2],"url":"https://base.garant.ru/12138291/45092b50986fdf828a39721a48054581/","cite":"п. 2 ч. 1 и ч. 2 ст. 157.2 ЖК РФ","explain":"При переходе к прямым договорам по основаниям прекращения договора с исполнителем из-за долга отдельное решение собрания не требуется.","review":false},{"id":190,"q":"Каким способом до сведения собственников помещений в многоквартирном доме доводится информация о перечне мероприятий по энергосбережению в многоквартирном доме организацией, осуществляющей поставки, продажу коммунальных ресурсов?","o":["способами, определяемыми общим собранием собственников помещений в многоквартирном доме","путем размещения информации в подъездах многоквартирного дома и (или) других помещениях, относящихся к общему имуществу собственников помещений в многоквартирном доме, а также иными способами","путем размещения информации в государственной информационной системе жилищно-коммунального хозяйства"],"a":[1],"url":"https://base.garant.ru/12171109/b6e02e45ca70d110df0019b9fe339c70/","cite":"ч. 6 ст. 12 Закона № 261-ФЗ","explain":"Перечень мероприятий размещают в подъездах и/или других общих помещениях, а также иными способами по усмотрению организации.","review":false},{"id":191,"q":"Каково минимальное расстояние от стен жилых домов до оси стволов деревьев с кроной диаметром до 5 м при озеленении придомовой территории жилых зданий?","o":["не менее 3 м","не менее 5 м","не менее 15 м"],"a":[1],"url":"https://base.garant.ru/76804504/","cite":"п. 9.6, таблица 9.1 СП 42.13330.2016","explain":"От наружной стены здания до оси ствола дерева принимают 5 м; применимость зависит от параметров дерева и иных требований к освещённости и сетям.","review":false},{"id":192,"q":"Какой срок установлен для внесения платы за жилое помещение и коммунальные услуги собственником помещения в многоквартирном доме?","o":["устанавливается договором управления многоквартирным домом","ежемесячно, до 15-го числа месяца, следующего за истекшим месяцем","ежемесячно, до 10-го числа месяца, следующего за истекшим расчетным периодом, за который производится оплата, если договором управления многоквартирным домом либо решением общего собрания членов товарищества собственников жилья или кооператива (при предоставлении коммунальных услуг товариществом или кооперативом) не установлен иной срок внесения платы за коммунальные услуги"],"a":[1],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 1 ст. 155 ЖК РФ","explain":"С 1 марта 2026 года общий срок оплаты — до 15-го числа следующего месяца. Прежний ответ о 10-м числе устарел.","review":false},{"id":193,"q":"Что является основанием для внесения ежемесячной платы за жилое помещение и коммунальные услуги?","o":["платежные документы (в том числе в электронной форме, размещенные в государственной информационной системе жилищно-коммунального хозяйства)","платежные документы (в том числе в электронной форме, размещенные в государственной информационной системе жилищно-коммунального хозяйства), информация о размере платы за жилое помещение и коммунальные услуги, задолженности по оплате жилых помещений и коммунальных услуг, размещенная в государственной информационной системе жилищно-коммунального хозяйства или в иных информационных системах, позволяющих внести плату за жилое помещение и коммунальные услуги)","информация о размере платы за жилое помещение и коммунальные услуги, задолженности по оплате жилых помещений и коммунальных услуг, размещенная в государственной информационной системе жилищно-коммунального хозяйства"],"a":[1],"url":"https://base.garant.ru/12138291/7857a3686529a3bb96e86e89fe5b1de8/","cite":"ч. 2 ст. 155 ЖК РФ","explain":"Основанием могут быть платёжные документы и предусмотренная законом информация о начислениях и задолженности в информационных системах.","review":false},{"id":194,"q":"Каким образом определяется доля собственника помещения в многоквартирном доме в праве на денежные средства фонда капитального ремонта общего имущества собственников помещений в многоквартирном доме, находящиеся на специальном счете, уплаченные собственником такого помещения?","o":["пропорционально размеру общей площади жилого помещения","пропорционально суммарному размеру взносов на капитальный ремонт, уплаченных собственником помещения и предшествующим собственником помещения","признается равной для всех собственников помещений в многоквартирном доме"],"a":[1],"url":"https://base.garant.ru/12138291/512c4e44002fbfcca5def9a03a754a00/","cite":"ч. 2 ст. 36.1 ЖК РФ","explain":"Доля в средствах спецсчёта пропорциональна сумме взносов, внесённых собственником и его предшественником, а не автоматически площади.","review":false},{"id":195,"q":"Каким видом нормативного правового акта определены состав, сроки и периодичность размещения информации в государственной информационной системе жилищно-коммунального хозяйства?","o":["постановление Правительства Российской Федерации","нормативный правовой акт федерального органа исполнительной власти","законодательством Российской Федерации не установлены"],"a":[1],"url":"https://base.garant.ru/70700450/e88847e78ccd9fdb54482c7fa15982bf/","cite":"ч. 3 ст. 7 Закона № 209-ФЗ; ч. 10.1 ст. 161 ЖК РФ","explain":"Состав, сроки и периодичность размещения устанавливаются нормативными актами уполномоченных федеральных органов в пределах их компетенции.","review":false},{"id":196,"q":"Меры ответственности, установленные для исполнителя коммунальных услуг за нарушение санитарно-эпидемиологических требований к питьевой воде, а также к питьевому и хозяйственно-бытовому водоснабжению?","o":["административный штраф на должностных лиц - от двух тысяч до трех тысяч рублей; на лиц, осуществляющих предпринимательскую деятельность без образования юридического лица, - от двух тысяч до трех тысяч рублей или административное приостановление деятельности на срок до девяноста суток; на юридических лиц - от двадцати тысяч до тридцати тысяч рублей или административное приостановление деятельности на срок до девяноста суток","дисквалификация исполнителя коммунальных услуг","аннулирование лицензии на осуществление предпринимательской деятельности по управлению многоквартирными домами"],"a":[0],"url":"https://base.garant.ru/12125267/d4d1c020f5ac1ff694cd399cf1a90fc2/","cite":"ст. 6.5 КоАП РФ","explain":"Должностным лицам — 2–3 тыс., ИП — 2–3 тыс. или приостановление до 90 суток, юрлицам — 20–30 тыс. руб. или приостановление до 90 суток.","review":false}];
